    make('phy1-03',5,'mathematical',4,'একই সমতলে একই আদিবেগে নিক্ষিপ্ত দুটি প্রক্ষেপকের নিক্ষেপ কোণ θ ও (৯০°−θ)। বায়ুর বাধা উপেক্ষা করলে তাদের পাল্লা সম্পর্কে কী সত্য?',['দ্বিতীয়টির পাল্লা দ্বিগুণ','দুটি পাল্লা সমান','প্রথমটির পাল্লা সবসময় বেশি','দুটি পাল্লা শূন্য'],1,'প্রক্ষেপকের পাল্লা R = u²sin2θ/g। পরিপূরক কোণের জন্য sin[2(90°−θ)] = sin(180°−2θ) = sin2θ।','আদিবেগ ও g একই এবং নিক্ষেপ ও অবতরণ উচ্চতা সমান ধরে পাল্লা সমান হয়।','R = u² sin(2θ)/g','পরিপূরক কোণ মানেই একই সর্বোচ্চ উচ্চতা নয়; শুধু পাল্লা সমান।','খেলাধুলায় projectile trajectory বিশ্লেষণে কোণ ও পাল্লার সম্পর্ক কাজে লাগে।',['দুই কোণের জন্য R সূত্র লেখো।','ত্রিকোণমিতিক পরিচয় ব্যবহার করো।','দুই পাল্লা সমান দেখাও।']),
    make('phy1-04',1,'misconception',2,'বন্দুক থেকে গুলি ছোড়ার সময় বন্দুক পিছনে সরে যায়। নিউটনের তৃতীয় সূত্রে ক্রিয়া–প্রতিক্রিয়া বল কেন পরস্পরকে বাতিল করে না?',['তাদের মান সমান নয়','তারা একই বস্তুর ওপর ক্রিয়া করে না','তারা একই দিকে কাজ করে','একটি বল কাল্পনিক'],1,'ক্রিয়া ও প্রতিক্রিয়ার বল সমান মানের, বিপরীতমুখী, কিন্তু দুটি ভিন্ন বস্তুর ওপর ক্রিয়া করে।','গুলি বন্দুককে পিছনে ঠেলে দেয় এবং বন্দুক গুলিকে সামনে ঠেলে দেয়; এক বস্তুর free-body diagram-এ দুটো বল একসঙ্গে থাকে না।','F₁₂ = −F₂₁','সমান ও বিপরীত বল সবসময় একই বস্তুর ওপর কাজ করে—এটি ভুল ধারণা।','রিকয়েল, রকেট ও নৌকা থেকে লাফ দেওয়ার ঘটনাও এই নীতির উদাহরণ।',['দুটি বস্তুকে আলাদা করো।','প্রতিটি বস্তুর ওপর বল চিহ্নিত করো।','বল দুটি ভিন্ন free-body diagram-এ বসাও।']),
    make('phy1-04',17,'multiStep',4,'২ kg ও ৩ kg ভরের দুটি বস্তু একই সরলরেখায় যথাক্রমে +৪ m/s ও −২ m/s বেগে এসে যুক্ত হয়ে যায়। যুক্ত হওয়ার পর বেগ কত?',['+০.৪ m/s','−০.৪ m/s','+১.০ m/s','−১.০ m/s'],0,'সম্পূর্ণ অস্থিতিস্থাপক সংঘর্ষে বস্তু দুটি একসঙ্গে চলে। বাহ্যিক বলের impulsive প্রভাব নগণ্য হলে মোট ভরবেগ সংরক্ষিত।','প্রাথমিক ভরবেগ = 2×4 + 3×(−2) = 2 kg·m/s। মোট ভর 5 kg, তাই v = 2/5 = +0.4 m/s।','m₁u₁ + m₂u₂ = (m₁+m₂)v','সংঘর্ষের পর বস্তু যুক্ত হলেও গতিশক্তি সংরক্ষিত থাকে না; ভরবেগ সংরক্ষিত থাকে।','গাড়ির সংঘর্ষ বিশ্লেষণে momentum conservation ব্যবহৃত হয়।',['দিকসহ বেগ লিখো।','প্রাথমিক মোট ভরবেগ হিসাব করো।','মোট ভর দিয়ে ভাগ করো: v = 2/5 m/s।']),
    make('phy1-05',3,'graph',4,'পরিবর্তনশীল বল F(x)-এর বিরুদ্ধে x–অক্ষে সরানো বস্তুর কাজ কীভাবে পাওয়া যায়?',['F–x গ্রাফের ঢাল থেকে','F–x গ্রাফের নিচের ক্ষেত্রফল থেকে','শুধু সর্বোচ্চ বল থেকে','বলকে সময় দিয়ে ভাগ করে'],1,'পরিবর্তনশীল বলের ক্ষেত্রে ক্ষুদ্র কাজ dW = F(x)dx। সমাকলন করলে F–x গ্রাফের নিচের signed area পাওয়া যায়।','বল ঋণাত্মক হলে কাজ ঋণাত্মক হতে পারে; তাই ক্ষেত্রফলের চিহ্ন গুরুত্বপূর্ণ।','W = ∫ₓ₁ˣ² F(x) dx','গ্রাফের ঢাল বল নয়, বলের অবস্থান-অনুসারী পরিবর্তনের হার।','স্প্রিং প্রসারণে বলের পরিবর্তনশীলতার কারণে ত্রিভুজাকার ক্ষেত্রফল থেকে কাজ মেলে।',['অবস্থান-নির্ভর বল চিহ্নিত করো।','dW = Fdx লিখো।','সীমা অনুযায়ী সমাকলন করো।']),
    make('phy1-05',14,'conceptual',2,'মহাকর্ষ বলকে সংরক্ষণশীল বল বলা হয় কেন?',['কাজ কেবল পথের ওপর নির্ভর করে','বন্ধ পথে মোট কাজ শূন্য','বল সবসময় ধ্রুব','বস্তু স্থির থাকে'],1,'সংরক্ষণশীল বলের কাজ কেবল প্রাথমিক ও চূড়ান্ত অবস্থানের ওপর নির্ভর করে। যেকোনো বন্ধ পথে মোট কাজ শূন্য।','মহাকর্ষীয় বিভবশক্তি সংজ্ঞায়িত করা যায় বলে মহাকর্ষ বল conservative।','∮ F·dr = 0','সংরক্ষণশীল বল মানে বলের মান ধ্রুব—এটি ভুল।','গ্রহের কক্ষপথে মোট যান্ত্রিক শক্তির বিশ্লেষণে এই গুণ গুরুত্বপূর্ণ।',['সংরক্ষণশীল বলের সংজ্ঞা স্মরণ করো।','একটি বন্ধ পথ কল্পনা করো।','মোট কাজ শূন্য হওয়ার শর্ত প্রয়োগ করো।']),
    make('phy1-06',14,'scenario',2,'পৃথিবীর পৃষ্ঠ থেকে অনেক ওপরে গেলে g-এর মান কীভাবে বদলায়?',['বাড়ে','কমে','অপরিবর্তিত থাকে','প্রথমে অসীম হয়'],1,'পৃথিবীর কেন্দ্র থেকে দূরত্ব r বাড়লে g = GM/r² অনুসারে অভিকর্ষজ ত্বরণ কমে।','উচ্চতা h হলে r = R+h; তাই g(h) = GM/(R+h)²।','g(h) = g₀[R/(R+h)]²','g সব উচ্চতায় একই থাকে—এটি কেবল পৃথিবীপৃষ্ঠের নিকটবর্তী ক্ষুদ্র উচ্চতায় আনুমানিক গ্রহণযোগ্য।','উচ্চ কক্ষপথের উপগ্রহে পৃথিবীর অভিকর্ষজ ত্বরণ পৃষ্ঠের তুলনায় কম।',['কেন্দ্র থেকে দূরত্ব r নির্ধারণ করো।','g = GM/r² প্রয়োগ করো।','r বাড়লে g কমে সিদ্ধান্ত নাও।']),
    make('phy1-06',4,'misconception',2,'মুক্তপতনে থাকা লিফটের ভেতরের যাত্রীর আপাত ওজন শূন্য হয় কেন?',['পৃথিবীর মহাকর্ষ নেই','লিফট ও যাত্রী একই ত্বরণে পড়ে, মেঝের normal force শূন্য','যাত্রীর ভর শূন্য হয়','যাত্রী স্থির থাকে'],1,'আপাত ওজন হলো সমর্থন বল বা normal reaction। মুক্তপতনে যাত্রী ও লিফট একই g ত্বরণে পড়ে, ফলে মেঝে যাত্রীকে ঠেলে না।','মহাকর্ষ বল তখনও কাজ করে; কেবল সমর্থন বল শূন্য হয়।','N = m(g−a); মুক্তপতনে a = g ⇒ N = 0','ওজনহীনতা মানে মহাকর্ষ অনুপস্থিত নয়।','কক্ষপথে নভোচারীরা free fall অবস্থায় থাকায় weightlessness অনুভব করেন।',['আপাত ওজনকে N হিসেবে ধরো।','লিফটের ত্বরণ নিচের দিকে g বসাও।','N = 0 পাও।']),
    make('phy1-07',4,'mathematical',2,'ইয়ং-এর গুণাঙ্কের সংজ্ঞা কোনটি?',['পীড়ন/বিকৃতি','বিকৃতি/পীড়ন','বল×সরণ','ভর/আয়তন'],0,'ইয়ং-এর গুণাঙ্ক হলো দৈর্ঘ্য বরাবর normal stress ও longitudinal strain-এর অনুপাত, elastic limit-এর মধ্যে।','পীড়ন একক ক্ষেত্রফলে বল এবং বিকৃতি মাত্রাহীন।','Y = stress/strain = (F/A)/(ΔL/L)','বিকৃতি ও পীড়নের অনুপাতই ইয়ং-এর গুণাঙ্ক নয়; সেটি reciprocal।','সেতু বা তারের প্রসারণ নির্ণয়ে Young modulus ব্যবহৃত হয়।',['পীড়ন = F/A নির্ণয় করো।','বিকৃতি = ΔL/L লেখো।','দুটি অনুপাত করো।']),
    make('phy1-07',19,'scenario',3,'তরলে পড়ন্ত ছোট গোলক প্রান্তিক বেগে পৌঁছালে কোন শর্তটি পূরণ হয়?',['ওজন শূন্য','নিট বল শূন্য; ওজন = প্লবতা + সান্দ্র প্রতিরোধ','সান্দ্র বল শূন্য','ত্বরণ সর্বোচ্চ'],1,'প্রান্তিক বেগে বস্তুর বেগ ধ্রুব হয়, তাই ত্বরণ শূন্য এবং নিট বল শূন্য।','নিচের দিকে ওজনের সঙ্গে ওপরের দিকে প্লবতা ও সান্দ্র প্রতিরোধের যোগফল সমান হয়।','mg = Fᵦ + Fᵥ (প্রান্তিক বেগে)','প্রান্তিক বেগ মানে বস্তু থেমে যায় না; ধ্রুব বেগে চলে।','তেলে পড়া বলের terminal velocity থেকে সান্দ্রতা নির্ণয় করা যায়।',['বলের free-body diagram আঁকো।','প্রান্তিক বেগে a = 0 বসাও।','ওজন ও ঊর্ধ্বমুখী বলের সাম্য লেখো।']),
    make('phy1-08',5,'mathematical',2,'আদর্শ স্প্রিং–ভর ব্যবস্থার পর্যায়কাল T কোন রাশির ওপর নির্ভর করে?',['T = 2π√(k/m)','T = 2π√(m/k)','T = mk','T = 2πm/k'],1,'স্প্রিংয়ের সরল ছন্দিত গতিতে angular frequency ω = √(k/m), তাই T = 2π/ω।','ভর বাড়ালে পর্যায়কাল বাড়ে; spring constant বাড়ালে কমে।','T = 2π√(m/k)','স্প্রিংয়ের SHM পর্যায়কাল আদর্শ ক্ষেত্রে বিস্তারের ওপর নির্ভর করে না।','সিসমিক সেন্সর ও কম্পন-পরীক্ষায় এই সম্পর্ক ব্যবহৃত হয়।',['ω = √(k/m) লেখো।','T = 2π/ω বসাও।','সরলীকরণ করো।']),
    make('phy1-08',2,'conceptual',2,'SHM-এ সাম্যাবস্থা থেকে সরণ x হলে ত্বরণের দিক ও মান সম্পর্কে সঠিক বক্তব্য কোনটি?',['a = +ω²x','a = −ω²x','a = ωx','a = ধ্রুব'],1,'SHM-এর restoring acceleration সরণের সমানুপাতিক কিন্তু বিপরীতমুখী।','বস্তু সাম্যাবস্থা থেকে যে দিকে সরে, ত্বরণ তাকে সাম্যাবস্থায় ফিরিয়ে আনার দিকে কাজ করে।','a = −ω²x','সরণ দ্বিগুণ হলে ত্বরণের মান অর্ধেক হয়—এটি ভুল; মান দ্বিগুণ হয়।','স্প্রিংয়ের oscillation-এ restoring acceleration দেখা যায়।',['সরণের দিক নির্ধারণ করো।','পুনঃস্থাপন ত্বরণ বিপরীত দিকে চিহ্নিত করো।','সমানুপাতিক ধ্রুবক ω² বসাও।']),
    make('phy1-08',7,'experiment',3,'সরল দোলকের দৈর্ঘ্য দ্বিগুণ করলে (ক্ষুদ্র দোলন, g ধ্রুব) পর্যায়কাল কীভাবে বদলায়?',['অর্ধেক','√2 গুণ','দ্বিগুণ','অপরিবর্তিত'],1,'ক্ষুদ্র কৌণিক বিস্তারে সরল দোলকের পর্যায়কাল T = 2π√(L/g)।','দৈর্ঘ্য L দ্বিগুণ করলে T′/T = √(2L/L) = √2। তাই পর্যায়কাল √2 গুণ হয়, দ্বিগুণ নয়।','T = 2π√(L/g),  T′ = √2 T','দৈর্ঘ্য দ্বিগুণ হলেই পর্যায়কাল দ্বিগুণ হয়—এটি ভুল; সূত্রে দৈর্ঘ্যের বর্গমূল আছে।','Pendulum clock-এ দৈর্ঘ্য বদলালে ঘড়ির দোলনের সময় বদলায়।',['মূল ও নতুন পর্যায়কাল লিখো।','L′ = 2L বসাও।','T′/T = √2 নির্ণয় করো।']),
    make('phy1-09',11,'mathematical',2,'৪৪ Hz ও ৪৮ Hz কম্পাঙ্কের দুটি কাছাকাছি সুর একসঙ্গে বাজলে প্রতি সেকেন্ডে বিটের সংখ্যা কত?',['২','৪','৪৪','৯২'],1,'বিটের কম্পাঙ্ক দুই তরঙ্গের কম্পাঙ্কের পার্থক্যের মান।','|48−44| = 4 Hz; তাই প্রতি সেকেন্ডে চারটি beat হয়।','fᵦ = |f₁−f₂|','বিট কম্পাঙ্ক দুই কম্পাঙ্কের যোগফল নয়।','বাদ্যযন্ত্র সুরে মেলাতে বিট শোনা হয়।',['দুটি কম্পাঙ্ক লেখো।','পার্থক্যের মান নাও।','৪ Hz-কে প্রতি সেকেন্ডে ৪ বিট বোঝো।']),
    make('phy1-09',7,'experiment',3,'দুই প্রান্তে স্থির একটি তারে মৌলিক স্থির তরঙ্গ সৃষ্টি হলে তার দৈর্ঘ্য L ও তরঙ্গদৈর্ঘ্য λ-এর সম্পর্ক কী?',['L = λ/4','L = λ/2','L = λ','L = 2λ'],1,'মৌলিক mode-এ তারের দুই প্রান্ত node এবং মাঝখানে antinode থাকে। দুই node-এর দূরত্ব অর্ধ তরঙ্গদৈর্ঘ্য।','তাই তারের দৈর্ঘ্যে অর্ধ তরঙ্গ অন্তর্ভুক্ত হয়।','L = λ/2','প্রান্তদ্বয় node হলে L এক পূর্ণ তরঙ্গদৈর্ঘ্য—এটি মৌলিক mode-এর ক্ষেত্রে ভুল।','তার বাদ্যযন্ত্রে স্থির তরঙ্গের mode সুর নির্ধারণ করে।',['দুই প্রান্তে node চিহ্নিত করো।','মৌলিক mode-এর মাঝখানের antinode বসাও।','node-to-node দূরত্ব λ/2 ব্যবহার করো।']),
    make('phy1-10',6,'analytical',2,'আদর্শ গ্যাসের তাপমাত্রা বাড়লে অণুর মূল গড় বর্গবেগ (rms speed) কীভাবে বদলায়, ভর অপরিবর্তিত থাকলে?',['T-এর সমানুপাতিক','√T-এর সমানুপাতিক','1/T-এর সমানুপাতিক','অপরিবর্তিত'],1,'গতিতত্ত্বে rms speed পরম তাপমাত্রার বর্গমূলের সমানুপাতিক।','তাপমাত্রা চার গুণ হলে rms speed দ্বিগুণ হয়; কারণ গতি শক্তি T-এর সঙ্গে সরাসরি বাড়ে।','vᵣₘₛ = √(3kT/m) = √(3RT/M)','rms speed তাপমাত্রার সঙ্গে সরাসরি T অনুপাতে বাড়ে না।','গ্যাসের বিসরণ ও অণুর সংঘর্ষের হার তাপমাত্রার সঙ্গে বদলায়।',['rms সূত্র লেখো।','গ্যাসের অণুর ভর ধ্রুব ধরো।','vᵣₘₛ ∝ √T নির্ণয় করো।']),
    make('phy1-10',10,'conceptual',3,'একপরমাণুক আদর্শ গ্যাসের একটি অণুর গড় অনুবাদী গতিশক্তি কত?',['kT','(1/2)kT','(3/2)kT','3kT'],2,'একপরমাণুক গ্যাসে তিনটি স্বাধীন অনুবাদী degrees of freedom আছে। শক্তির সমবিভাজন নীতি অনুযায়ী প্রত্যেক quadratic স্বাধীনতার জন্য গড় শক্তি (1/2)kT।','তিনটি অনুবাদী স্বাধীনতার মোট গড় শক্তি 3×(1/2)kT।','⟨K⟩ = (3/2)kT','একপরমাণুক গ্যাসে ঘূর্ণন স্বাধীনতা সাধারণ তাপমাত্রায় একইভাবে সক্রিয় নয়।','গ্যাসের তাপমাত্রা ও অণুর গতিশক্তির সম্পর্ক এ সূত্রে বোঝা যায়।',['স্বাধীনতার সংখ্যা f = 3 নাও।','প্রতি স্বাধীনতায় (1/2)kT প্রয়োগ করো।','মোট শক্তি 3kT/2।']),
    // Physics — Second paper (11 chapters)
    make('phy2-01',5,'conceptual',3,'তাপগতিবিদ্যার প্রচলিত sign convention-এ Q হলো সিস্টেমে সরবরাহকৃত তাপ এবং W হলো সিস্টেমের করা কাজ। প্রথম সূত্র কোনটি?',['ΔU = Q + W','ΔU = Q − W','ΔU = W − Q','ΔU = 0 সবসময়'],1,'সিস্টেমে তাপ প্রবেশে অভ্যন্তরীণ শক্তি বাড়ে; সিস্টেম কাজ করলে শক্তি বের হয়। তাই ΔU = Q−W।','এখানে W positive যখন system surroundings-এর ওপর কাজ করে। বইয়ের convention ভিন্ন হলে সূত্রের sign সংজ্ঞা মিলিয়ে নিতে হয়।','ΔU = Q − W','সব বইয়ে W-এর sign convention একই—এ ধারণা ঠিক নয়; কাজের সংজ্ঞা স্পষ্ট করতে হবে।','ইঞ্জিনের শক্তি balance করতে প্রথম সূত্র ব্যবহার করা হয়।',['Q-এর দিক ও W-এর সংজ্ঞা স্থির করো।','সিস্টেমে প্রবেশ ও বের হওয়া শক্তি চিহ্নিত করো।','ΔU = Q−W লেখো।']),
    make('phy2-01',8,'mathematical',4,'একটি কার্নো ইঞ্জিন ৫০০ K উষ্ণ উৎস ও ৩০০ K শীতল গ্রাহকের মধ্যে কাজ করে। সর্বোচ্চ দক্ষতা কত?',['২০%','৪০%','৬০%','৮০%'],1,'কার্নো ইঞ্জিনের দক্ষতা কেবল উষ্ণ ও শীতল reservoir-এর পরম তাপমাত্রার ওপর নির্ভর করে।','η = 1−Tc/Th = 1−300/500 = 0.4 বা 40%।','η = 1 − T_c/T_h','তাপমাত্রা Celsius-এ বসালে দক্ষতা ভুল হবে; Kelvin ব্যবহার আবশ্যক।','বাস্তব ইঞ্জিনের দক্ষতা একই তাপমাত্রা সীমায় কার্নো দক্ষতার বেশি হতে পারে না।',['Tc ও Th Kelvin-এ লেখো।','অনুপাত 300/500 হিসাব করো।','১ থেকে বিয়োগ করে শতাংশে রূপান্তর করো।']),
    make('phy2-02',11,'mathematical',2,'একটি ধারক C-তে বিভব পার্থক্য V প্রয়োগ করা হলে সঞ্চিত শক্তি কোনটি?',['CV²','(1/2)CV²','2CV²','C/V²'],1,'ধারক চার্জ করার সময় বিভব ধীরে 0 থেকে V-তে বাড়ে। তাই শক্তি হলো ∫Vdq = ∫(q/C)dq।','q = CV বসালে U = Q²/(2C) = CV²/2 পাওয়া যায়।','U = ½CV² = Q²/(2C)','শক্তি CV² নয়; চার্জ করার সময় গড় বিভব V/2 হওয়ায় 1/2 ফ্যাক্টর আসে।','ক্যামেরার flash capacitor-এ শক্তি সঞ্চিত থাকে।',['V = q/C লিখো।','U = ∫₀ᴽVdq ব্যবহার করো।','q = CV বসিয়ে ফল সরল করো।']),
    make('phy2-02',3,'conceptual',2,'সমবিভব তলের ওপর একটি চার্জ সরালে তড়িৎক্ষেত্রের বিরুদ্ধে সম্পাদিত কাজ কত?',['শূন্য','সর্বোচ্চ','চার্জের দ্বিগুণ','পথের দৈর্ঘ্যের সমানুপাতিক'],0,'সমবিভব তলের প্রতিটি বিন্দুর বিভব সমান। তাই দুই বিন্দুর বিভব পার্থক্য শূন্য।','বিভব পার্থক্য শূন্য হলে W = qΔV = 0।','W = q(V₂−V₁)','সমবিভব পৃষ্ঠে ক্ষেত্র শূন্য—এ ধারণা ভুল; ক্ষেত্র পৃষ্ঠের লম্ব হতে পারে।','ইলেকট্রনিক সার্কিটে equipotential region বিশ্লেষণে এটি কাজে লাগে।',['প্রারম্ভিক ও চূড়ান্ত বিভব তুলনা করো।','ΔV = 0 লেখো।','W = qΔV থেকে কাজ শূন্য পাও।']),
    make('phy2-03',3,'mathematical',4,'একটি কোষের তড়িচ্চালক বল ১২ V, অভ্যন্তরীণ রোধ ১ Ω এবং বহিঃরোধ ৫ Ω। টার্মিনাল বিভব কত?',['২ V','১০ V','১২ V','১৪ V'],1,'বর্তনীতে ধারা I = E/(R+r) = 12/6 = 2 A। কোষ discharge করলে terminal voltage V = E−Ir।','V = 12−2×1 = 10 V; এটিই বহিঃরোধে বিভবপতন IR।','I = E/(R+r), V = E−Ir = IR','টার্মিনাল বিভব সবসময় emf-এর সমান নয়; অভ্যন্তরীণ রোধে বিভবপতন হয়।','ব্যাটারি লোডে যুক্ত হলে terminal voltage কমে যাওয়ার কারণ এটি।',['মোট রোধ 6 Ω হিসাব করো।','I = 12/6 = 2 A বের করো।','V = 12−2×1 = 10 V।']),
    make('phy2-03',5,'conceptual',2,'একটি junction-এ ৩ A ও ২ A ধারা প্রবেশ করে। একটি শাখা দিয়ে ৪ A বের হলে অন্য বহির্গামী শাখার ধারা কত?',['১ A','২ A','৩ A','৫ A'],0,'Kirchhoff-এর junction rule অনুযায়ী node-এ প্রবেশকারী মোট ধারা = বের হওয়া মোট ধারা।','প্রবেশ 5 A; একটি বহির্গামী 4 A, তাই অন্যটি 1 A।','ΣI_in = ΣI_out','junction-এ চার্জ জমা না থাকলে current conservation মানতে হয়।','জটিল বৈদ্যুতিক network-এ অজানা ধারা নির্ণয়ে এটি লাগে।',['প্রবেশকারী ধারা যোগ করো।','মোট বহির্গামী ধারার সমান করো।','5−4 = 1 A বের করো।']),
    make('phy2-04',3,'mathematical',2,'একটি ধনাত্মক চার্জ q বেগ v-তে চৌম্বক ক্ষেত্র B-এর সমান্তরালে চলে। চৌম্বক বল কত?',['qvB','শূন্য','qB/v','qv/B'],1,'চৌম্বক বল F = qvBsinθ। বেগ ও ক্ষেত্র সমান্তরাল হওয়ায় θ = 0°।','sin0 = 0, তাই বল শূন্য।','F = qvB sinθ','চৌম্বক ক্ষেত্র সব চলন্ত চার্জকে বল দেয় না; বেগের লম্ব উপাংশ প্রয়োজন।','কণার beam-কে চৌম্বক ক্ষেত্র দিয়ে বাঁকাতে velocity component গুরুত্বপূর্ণ।',['v ও B-এর কোণ নির্ণয় করো।','θ = 0° বসাও।','sin0 = 0 থেকে F = 0।']),
    make('phy2-04',9,'scenario',3,'একটি দীর্ঘ solenoid-এর ভেতরে নরম লোহার core ঢোকালে চৌম্বক ক্ষেত্র সাধারণত বাড়ে কেন?',['লোহা ধারা শূন্য করে','core-এর উচ্চ permeability চৌম্বক ফ্লাক্স বাড়ায়','solenoid-এর দৈর্ঘ্য শূন্য হয়','কয়েলের পাক কমে যায়'],1,'নরম লোহার relative permeability বেশি। ফলে একই magnetizing field-এ core-এর ভেতর magnetic flux density বাড়ে।','লোহার domain-গুলো বাহ্যিক ক্ষেত্রের দিকে আংশিক সাজে; তাই solenoid electromagnet হিসেবে শক্তিশালী হয়।','B = μH, যেখানে μ = μ₀μᵣ','লোহা নিজে থেকে সবসময় স্থায়ী চুম্বক—এটি ঠিক নয়; soft iron সহজে magnetize ও demagnetize হয়।','ইলেকট্রিক রিলে ও electromagnet-এ soft iron core ব্যবহৃত হয়।',['Solenoid-এর H প্রায় নির্দিষ্ট ধরো।','Core-এর μᵣ বেশি বোঝো।','B = μH থেকে flux density বৃদ্ধি নির্ণয় করো।']),
    make('phy2-05',3,'conceptual',3,'চুম্বকের উত্তর মেরু একটি বন্ধ কুণ্ডলীর দিকে এগিয়ে আনা হলে লেঞ্জের সূত্র অনুযায়ী কুণ্ডলী কীভাবে প্রতিক্রিয়া করে?',['আবিষ্ট ক্ষেত্র পরিবর্তনকে সহায়তা করে','আবিষ্ট ক্ষেত্র চৌম্বক ফ্লাক্সের পরিবর্তনকে বাধা দেয়','কোনো ধারা হয় না','কুণ্ডলী সবসময় আকর্ষণ করে'],1,'লেঞ্জের সূত্রে আবিষ্ট ধারা এমন দিকের চৌম্বক ক্ষেত্র তৈরি করে যা ফ্লাক্সের পরিবর্তনকে বাধা দেয়।','উত্তর মেরু এগিয়ে এলে কুণ্ডলীর নিকট প্রান্তও উত্তর মেরুর মতো হয়, যাতে আগমনকে প্রতিহত করে।','ε = −dΦ_B/dt','আবিষ্ট ক্ষেত্র মূল চৌম্বক ক্ষেত্রকে সবসময় বাতিল করে না; পরিবর্তনের বিরোধিতা করে।','জেনারেটর ও electromagnetic braking-এ Lenz law কার্যকর।',['বাহ্যিক ফ্লাক্স বাড়ছে কি না বোঝো।','বাড়ার বিরোধী ক্ষেত্রের দিক নির্ণয় করো।','কুণ্ডলীর নিকট প্রান্তের polarity নির্ধারণ করো।']),
    make('phy2-05',8,'mathematical',2,'সাইনুসয়েডাল AC-এর সর্বোচ্চ ভোল্টেজ ২০০ V হলে rms ভোল্টেজ কত (প্রায়)?',['১০০ V','১৪১ V','২০০ V','২৮৩ V'],1,'সাইনুসয়েডাল AC-এর rms মান peak-এর 1/√2 গুণ।','200/√2 ≈ 141.4 V।','V_rms = V₀/√2','rms মান peak-এর সমান নয়; এটি সমতুল্য DC heating effect নির্দেশ করে।','বাসাবাড়ির AC rating rms মানে প্রকাশ করা হয়।',['peak voltage চিহ্নিত করো।','√2 দিয়ে ভাগ করো।','প্রায় 141 V লেখো।']),
    make('phy2-06',7,'scenario',2,'ঘন মাধ্যম থেকে লঘু মাধ্যমে আলো গেলে আপতন কোণ সংকট কোণের বেশি হলে কী ঘটে?',['প্রতিসরণই হয়','পূর্ণ অভ্যন্তরীণ প্রতিফলন','আলো শোষিত হয়','আলোর বেগ অসীম হয়'],1,'পূর্ণ অভ্যন্তরীণ প্রতিফলনের জন্য আলোকে উচ্চ প্রতিসরাঙ্কের মাধ্যম থেকে নিম্ন প্রতিসরাঙ্কের মাধ্যমে যেতে হয় এবং আপতন কোণ সংকট কোণের বেশি হতে হয়।','দুটি শর্ত একসঙ্গে পূর্ণ হলে দ্বিতীয় মাধ্যমে প্রতিসরিত রশ্মি থাকে না; আলো প্রথম মাধ্যমেই প্রতিফলিত হয়।','sin C = n₂/n₁ (n₁>n₂)','যেকোনো দুটি মাধ্যমের সীমানায় TIR ঘটে না; দিক ও critical angle-এর শর্ত দরকার।','অপটিক্যাল ফাইবারে আলোর guiding-এর ভিত্তি TIR।',['n₁>n₂ নিশ্চিত করো।','আপতন কোণ C-এর সঙ্গে তুলনা করো।','i>C হলে TIR সিদ্ধান্ত নাও।']),
    make('phy2-06',3,'conceptual',2,'একটি উত্তল লেন্সে বস্তু 2f-এর বাইরে রাখা হলে বাস্তব প্রতিবিম্ব কোথায় গঠিত হয়?',['লেন্স ও f-এর মাঝখানে','f ও 2f-এর মধ্যে','2f-এর বাইরে','অসীমে'],1,'উত্তল লেন্সের ray diagram অনুযায়ী বস্তু 2f-এর বাইরে থাকলে প্রতিবিম্ব অপর পাশে f ও 2f-এর মধ্যে গঠিত হয়।','প্রতিবিম্ব বাস্তব, উল্টো ও আকারে খাটো হয়।','লেন্স সূত্র: 1/f = 1/v − 1/u (Cartesian convention)','বস্তু 2f-এর বাইরে থাকলে প্রতিবিম্বও 2f-এর বাইরে হয়—এটি ভুল।','ক্যামেরা লেন্সে সেন্সরে বাস্তব প্রতিবিম্ব গঠিত হয়।',['প্রধান অক্ষ ও f, 2f চিহ্নিত করো।','দুটি প্রধান রশ্মি আঁকো।','ছেদবিন্দু f ও 2f-এর মধ্যে শনাক্ত করো।']),
    make('phy2-07',7,'mathematical',2,'Young-এর দ্বি-চিড় পরীক্ষায় λ ও d অপরিবর্তিত রেখে পর্দার দূরত্ব D দ্বিগুণ করলে fringe width কী হবে?',['অর্ধেক','দ্বিগুণ','চার গুণ','অপরিবর্তিত'],1,'Fringe width β = λD/d। তাই D দ্বিগুণ করলে β-ও দ্বিগুণ হয়।','এটি সমান দূরত্বের উজ্জ্বল ও অন্ধকার fringe-এর ব্যবধান।','β = λD/d','চিড়ের দূরত্ব d বাড়ালে fringe width বাড়ে না; বরং কমে।','ইন্টারফেরোমেট্রি ও তরঙ্গদৈর্ঘ্য মাপায় YDSE সম্পর্ক লাগে।',['β সূত্র লেখো।','D-কে 2D বসাও।','নতুন β = 2β নির্ণয় করো।']),
    make('phy2-07',5,'conceptual',2,'আলোকে সমতল মেরুকরণ করা সম্ভব হওয়া কোন বৈশিষ্ট্যের প্রমাণ?',['আলো অনুদৈর্ঘ্য','আলো আড় তরঙ্গ','আলো কেবল কণিকা','আলো শব্দতরঙ্গ'],1,'Polarization দেখায় যে আলোর কম্পন প্রচারের দিকের লম্ব একটি নির্দিষ্ট সমতলে সীমাবদ্ধ করা যায়। এটি transverse wave-এর বৈশিষ্ট্য।','অনুদৈর্ঘ্য তরঙ্গে কম্পন propagation direction বরাবর; সাধারণভাবে এভাবে plane polarized করা যায় না।','E ⟂ propagation direction','মেরুকরণকে interference-এর সমার্থক ভাবা যাবে না।','Polarizing sunglasses প্রতিফলিত glare কমাতে সাহায্য করে।',['কম্পনের দিক ও propagation direction আলাদা করো।','Polarizer-এর নির্বাচিত দিক বোঝো।','Transverse nature সিদ্ধান্ত নাও।']),
    make('phy2-08',1,'conceptual',4,'কোনো ধাতুর ওপর আলো ফেলেও যদি photoelectron নির্গত না হয়, তবে তীব্রতা বাড়ানো কেন সবসময় সমাধান নয়?',['তীব্রতা photon সংখ্যা বাড়ায়, কিন্তু threshold frequency না পেরোলে প্রতিটি photon-এর শক্তি অপর্যাপ্ত','তীব্রতা সবসময় frequency কমায়','ইলেকট্রনের ভর বাড়ে','ধাতুতে electron থাকে না'],0,'Photoelectric effect-এ একটি photon-এর শক্তি E = hf। নির্গমনের জন্য তা work function φ-এর সমান বা বেশি হতে হয়।','frequency threshold-এর নিচে থাকলে intensity বাড়িয়ে বেশি সংখ্যক কম শক্তির photon দিলেও নির্গমন শুরু হয় না।','K_max = hf − φ; f₀ = φ/h','শুধু আলো উজ্জ্বল করলে electron-এর সর্বোচ্চ গতিশক্তি বাড়ে—এটি ভুল; তা frequency-র ওপর নির্ভর করে।','Photocell ও light sensor photoelectric effect-ভিত্তিক।',['Photon energy hf নির্ণয়ের ধারণা নাও।','Work function φ-এর সঙ্গে তুলনা করো।','hf<φ হলে emission হবে না।']),
    make('phy2-08',9,'mathematical',2,'একটি কণার ভর অপরিবর্তিত রেখে তার বেগ দ্বিগুণ করলে de Broglie তরঙ্গদৈর্ঘ্য কী হয়?',['দ্বিগুণ','অর্ধেক','চার গুণ','অপরিবর্তিত'],1,'de Broglie তরঙ্গদৈর্ঘ্য λ = h/p = h/(mv)। ভর অপরিবর্তিত হলে বেগ দ্বিগুণে ভরবেগ দ্বিগুণ হয়।','ভরবেগ দ্বিগুণ হওয়ায় তরঙ্গদৈর্ঘ্য অর্ধেক হয়।','λ = h/(mv)','কণার বেগ দ্বিগুণে de Broglie wavelength দ্বিগুণ হয় না।','ইলেকট্রন diffraction-এ matter-wave ধারণা দেখা যায়।',['λ = h/mv লেখো।','v-কে 2v বসাও।','λ′ = λ/2 নির্ণয় করো।']),
    make('phy2-09',7,'mathematical',2,'একটি তেজস্ক্রিয় নমুনার অর্ধায়ু ৬ দিন। ১৮ দিন পর মূল নিউক্লিয়াসের কত অংশ অবশিষ্ট থাকবে?',['১/২','১/৪','১/৮','১/১৬'],2,'১৮ দিন হলো তিনটি অর্ধায়ু। প্রতিটি অর্ধায়ুতে অবশিষ্ট অংশ অর্ধেক হয়।','অবশিষ্ট ভগ্নাংশ (1/2)³ = 1/8।','N/N₀ = (1/2)^(t/T₁/₂)','১৮ দিনকে একটি অর্ধায়ু ধরে নেওয়া যাবে না; ৬ দিন করে তিনটি interval।','রেডিওআইসোটোপের বয়স ও চিকিৎসায় অবক্ষয় হিসাব করা হয়।',['n = 18/6 = 3 নির্ণয় করো।','(1/2)^n বসাও।','1/8 অবশিষ্ট পাও।']),
    make('phy2-09',10,'conceptual',3,'নিউক্লিয়াসের binding energy per nucleon বেশি হলে সাধারণত কী বোঝায়?',['নিউক্লিয়াস কম স্থিতিশীল','নিউক্লিয়াসকে পৃথক নিউক্লিয়নে ভাঙতে গড়ে বেশি শক্তি লাগে','নিউক্লিয়াসে নিউট্রন নেই','ভর সংরক্ষিত হয় না'],1,'Binding energy হলো নিউক্লিয়াসকে মুক্ত নিউক্লিয়নে বিচ্ছিন্ন করতে প্রয়োজনীয় শক্তি। প্রতি নিউক্লিয়নে বেশি binding energy সাধারণত বেশি স্থিতিশীলতার ইঙ্গিত।','মোট binding energy-কে nucleon সংখ্যা দিয়ে ভাগ করলে per nucleon পাওয়া যায়।','BE per nucleon = (Δmc²)/A','binding energy ও ভরসংখ্যা একই রাশি নয়।','Nuclear fission/fusion-এ binding energy curve থেকে শক্তি নিঃসরণ বোঝা যায়।',['ভর ত্রুটি Δm বুঝো।','BE = Δmc² নির্ণয় করো।','A দিয়ে ভাগ করে প্রতি nucleon-এর শক্তি তুলনা করো।']),
    make('phy2-10',1,'scenario',2,'একটি সাধারণ p–n junction diode-কে forward bias করতে কোন সংযোগটি প্রয়োজন?',['p পাশে negative, n পাশে positive','p পাশে positive, n পাশে negative','দুই পাশে একই terminal','কোনো battery নয়'],1,'Forward bias-এ বাহ্যিক battery-এর positive terminal p-side এবং negative terminal n-side-এ যুক্ত হয়।','এতে depletion barrier কমে এবং majority carrier junction অতিক্রম করতে পারে।','Forward bias: p → (+), n → (−)','Reverse bias-এও diode একইভাবে সহজে current বহন করে—এটি ভুল।','Rectifier circuit-এ diode-এর forward bias ব্যবহৃত হয়।',['p ও n অঞ্চল শনাক্ত করো।','বাধা কমাতে প্রয়োজনীয় polarity নির্ধারণ করো।','p-কে positive, n-কে negative যুক্ত করো।']),
    make('phy2-10',9,'analytical',4,'একটি NPN transistor-কে active region-এ amplifier হিসেবে চালাতে কোন biasing সঠিক?',['Emitter-base reverse, collector-base forward','Emitter-base forward, collector-base reverse','দুই junction-ই forward','দুই junction-ই reverse'],1,'NPN transistor-এর active region-এ emitter-base junction forward biased এবং collector-base junction reverse biased থাকে।','Emitter থেকে carrier base-এ প্রবেশ করে এবং collector-এর electric field অধিকাংশ carrier সংগ্রহ করে।','Active mode: EB forward, CB reverse','Transistor active amplification-এর জন্য দুই junction-ই forward করা হয় না।','Common-emitter amplifier-এ এই biasing ব্যবহার করা হয়।',['NPN layer structure মনে করো।','Emitter-base forward bias দাও।','Collector-base reverse bias নিশ্চিত করো।']),
    make('phy2-11',3,'mathematical',2,'নক্ষত্রের parallax angle ১ arcsecond হলে দূরত্ব কত parsec?',['০.৫ pc','১ pc','২ pc','১ আলোকবর্ষ'],1,'Parsec হলো সেই দূরত্ব যেখানে ১ astronomical unit এক arcsecond কোণ উৎপন্ন করে।','পারাল্যাক্স p arcsecond হলে d(parsec) = 1/p; p=1 হলে d=1 pc।','d(pc) = 1/p(arcsec)','Parallax angle যত বড়, দূরত্বও তত বড়—এটি উল্টো সম্পর্ক।','নিকটবর্তী নক্ষত্রের দূরত্ব নির্ণয়ে stellar parallax ব্যবহার হয়।',['p arcsecond-এ লেখো।','d = 1/p ব্যবহার করো।','১ parsec পাও।']),
    make('phy2-11',0,'interpretation',3,'কোনো দূরবর্তী ছায়াপথের বর্ণালির রেখা দীর্ঘতর তরঙ্গদৈর্ঘ্যের দিকে সরে গেলে সাধারণত কী বোঝায়?',['ছায়াপথ আমাদের দিকে আসছে','ছায়াপথ আমাদের থেকে দূরে সরে যাচ্ছে','আলো শব্দে পরিণত হয়েছে','ছায়াপথের তাপমাত্রা শূন্য'],1,'দূরে সরে যাওয়ার ক্ষেত্রে Doppler/cosmological redshift-এ বর্ণালির রেখা দীর্ঘতর তরঙ্গদৈর্ঘ্যে সরে যায়।','এটি মহাবিশ্বের প্রসারণের পর্যবেক্ষণগত প্রমাণের একটি; ব্যাখ্যায় মহাজাগতিক দূরত্ব ও redshift-এর প্রসঙ্গ গুরুত্বপূর্ণ।','z = (λ_obs−λ_emit)/λ_emit','Redshift-কে কেবল নক্ষত্রের লাল রঙ হওয়া হিসেবে ব্যাখ্যা করা যাবে না।','দূরবর্তী গ্যালাক্সির redshift মহাবিশ্বের বৃহৎ-স্কেলের গতি বিশ্লেষণে ব্যবহৃত হয়।',['পর্যবেক্ষিত ও নির্গত λ তুলনা করো।','λ_obs > λ_emit হলে z ধনাত্মক।','দূরে সরে যাওয়ার সঙ্গে সামঞ্জস্য দেখো।']),
    // Chemistry — First paper (5 chapters)
    make('chem1-01',6,'safety',1,'ঘন সালফিউরিক অ্যাসিড পাতলা করার সময় নিরাপদ পদ্ধতি কোনটি?',['পানির মধ্যে ধীরে অ্যাসিড যোগ করা','অ্যাসিডের মধ্যে দ্রুত পানি ঢালা','দুই তরল একসঙ্গে ঝাঁকানো','খোলা হাতে মেশানো'],0,'ঘন অ্যাসিডে পানি মেশালে প্রচুর তাপ উৎপন্ন হতে পারে। তাই পানি আগে নিয়ে নেড়ে ধীরে ধীরে অ্যাসিড যোগ করতে হয়।','এই পদ্ধতিতে স্থানীয় অতিরিক্ত উত্তাপ ও ছিটকে পড়ার ঝুঁকি কমে; সুরক্ষা চশমা ও উপযুক্ত PPE প্রয়োজন।','মনে রাখো: Always add acid to water, not water to acid.','পানি অ্যাসিডে ঢাললে সবসময় একইভাবে নিরাপদে পাতলা হয়—এটি বিপজ্জনক ভুল ধারণা।','ল্যাবরেটরিতে acid dilution-এর সময় এই নিয়ম মানা বাধ্যতামূলক।',['চোখ ও ত্বকের সুরক্ষা নিশ্চিত করো।','পাত্রে প্রয়োজনীয় পানি নাও।','নাড়তে নাড়তে অল্প অল্প করে অ্যাসিড যোগ করো।']),
    make('chem1-01',10,'scenario',2,'অজানা রাসায়নিক বর্জ্যের সঠিক ব্যবস্থাপনা কোনটি?',['সিঙ্কে ঢেলে দেওয়া','লেবেলসহ নির্ধারিত বর্জ্য পাত্রে রাখা','গরম করে বাষ্প করা','সাধারণ ডাস্টবিনে ফেলা'],1,'অজানা রাসায়নিকের পরিচয় ও ঝুঁকি নিশ্চিত না হওয়া পর্যন্ত সেটিকে সাধারণ বর্জ্যে ফেলা যাবে না।','বর্জ্যকে শ্রেণিভিত্তিক, লেবেলযুক্ত এবং প্রতিষ্ঠানের নিরাপত্তা নির্দেশনা অনুযায়ী সংগ্রহ করতে হয়।','নিরাপত্তা নীতি: identify → segregate → label → authorized disposal','পানিতে মিশিয়ে দিলেই রাসায়নিক নিরাপদ হয় না।','শিক্ষা ও শিল্প-ল্যাবের chemical waste management পরিবেশ দূষণ কমায়।',['রাসায়নিকের পরিচয় যাচাই করো।','সামঞ্জস্যপূর্ণ বর্জ্য পাত্র নির্বাচন করো।','লেবেল ও disposal record রাখো।']),
    make('chem1-02',8,'experiment',2,'দ্রবণে SO₄²⁻ আয়ন শনাক্ত করতে BaCl₂ যোগ করলে সাদা অবক্ষেপ তৈরি হয়। অবক্ষেপটি কোনটি?',['BaSO₄','BaCl₂','Na₂SO₄','H₂SO₄'],0,'Ba²⁺ ও SO₄²⁻ অল্প দ্রাব্য BaSO₄ তৈরি করে, যা সাদা অবক্ষেপ।','অম্লীয় মাধ্যমে পরীক্ষার নির্দিষ্ট শর্ত অনুসরণ করলে carbonate ইত্যাদির interference কমানো যায়।','Ba²⁺ + SO₄²⁻ → BaSO₄(s)','সাদা অবক্ষেপ মানেই সবসময় sulfate—পরীক্ষার reagent ও শর্ত যাচাই প্রয়োজন।','গুণগত বিশ্লেষণে আয়ন শনাক্ত করতে precipitation reaction ব্যবহৃত হয়।',['BaCl₂ থেকে Ba²⁺ শনাক্ত করো।','SO₄²⁻ যুক্ত করো।','অদ্রাব্য BaSO₄-এর সাদা অবক্ষেপ চিহ্নিত করো।']),
    make('chem1-02',1,'analytical',3,'NH₄⁺ আয়নযুক্ত লবণে NaOH যোগ করে গরম করলে কোন গ্যাস বের হয় যা স্যাঁতসেঁতে লাল লিটমাস নীল করে?',['CO₂','NH₃','Cl₂','SO₂'],1,'ক্ষারের উপস্থিতিতে ammonium ion থেকে ammonia gas মুক্ত হয়। NH₃ পানিতে দ্রবীভূত হয়ে ক্ষারীয় দ্রবণ তৈরি করে।','NH₃ গন্ধযুক্ত এবং আর্দ্র লাল litmus নীল করে; গ্যাস সরাসরি শোঁকা যাবে না, wafting technique দরকার।','NH₄⁺ + OH⁻ → NH₃↑ + H₂O','NH₄⁺ পরীক্ষায় গ্যাসকে নাকে সরাসরি নেওয়া নিরাপদ নয়।','লবণের qualitative analysis-এ ammonium ion শনাক্তকরণ গুরুত্বপূর্ণ।',['NaOH-এর OH⁻ চিহ্নিত করো।','NH₄⁺ থেকে NH₃ মুক্তির বিক্রিয়া লেখো।','NH₃-এর ক্ষারীয় প্রভাব চিনো।']),
    make('chem1-03',8,'trend',2,'একই পর্যায়ে বাম থেকে ডানে গেলে প্রথম আয়নীকরণ শক্তি সাধারণত কীভাবে বদলায়?',['কমে','বাড়ে','সবসময় অপরিবর্তিত','শূন্য হয়'],1,'একই পর্যায়ে কার্যকর নিউক্লীয় চার্জ সাধারণত বাড়ে এবং atomic radius কমে। ফলে বহিঃস্থ electron অপসারণে বেশি শক্তি লাগে।','কিছু ব্যতিক্রম থাকে (যেমন উপস্তর পূর্ণতা/অর্ধপূর্ণতা), তাই “সাধারণত” শব্দটি গুরুত্বপূর্ণ।','X(g) → X⁺(g) + e⁻; IE₁ = প্রয়োজনীয় শক্তি','পর্যায় জুড়ে trend সম্পূর্ণ সরলরৈখিক ও ব্যতিক্রমহীন নয়।','মৌলের রাসায়নিক বিক্রিয়াশীলতা ব্যাখ্যায় ionization energy কাজে লাগে।',['পর্যায় জুড়ে nuclear charge পরিবর্তন দেখো।','shielding তুলনামূলক কম বদলায় বুঝো।','electron অপসারণ কঠিন হওয়ায় IE বাড়ে।']),
    make('chem1-03',4,'conceptual',4,'VSEPR তত্ত্ব অনুযায়ী NH₃ ও H₂O—দুটিরই central atom-এ lone pair থাকায় bond angle কমে। H₂O-এর কোণ NH₃-এর চেয়ে ছোট কেন?',['H₂O-তে lone pair বেশি','NH₃-তে lone pair বেশি','O পরমাণুর ভর কম','H₂O-তে বন্ধন নেই'],0,'NH₃-তে N-এর একটি lone pair, H₂O-তে O-এর দুটি lone pair। Lone pair–lone pair ও lone pair–bond pair বিকর্ষণ bond angle সংকুচিত করে।','H₂O-তে lone pair-এর সংখ্যা বেশি; তাই H–O–H কোণ (প্রায় 104.5°) NH₃-এর H–N–H কোণের (প্রায় 107°) চেয়ে ছোট।','LP–LP > LP–BP > BP–BP repulsion','দুটি অণুই একই electron-pair geometry হলেও molecular shape ও bond angle সমান নয়।','অণুর আকৃতি ও polarity বোঝাতে VSEPR ব্যবহৃত হয়।',['কেন্দ্রীয় পরমাণুর valence electron গুনো।','lone pair-এর সংখ্যা নির্ণয় করো।','বিকর্ষণ বেশি হলে bond angle বেশি সংকুচিত বোঝো।']),
    make('chem1-04',5,'misconception',2,'একটি অনুঘটক সাম্যাবস্থায় পৌঁছানোর সময়কে প্রভাবিত করে, কিন্তু সাম্য ধ্রুবক বদলায় না কেন?',['এটি forward ও reverse উভয় বিক্রিয়ার activation energy কমায়','এটি শুধু উৎপাদের শক্তি বদলায়','এটি সব বিক্রিয়া বন্ধ করে','এটি তাপমাত্রা সবসময় বাড়ায়'],0,'অনুঘটক বিক্রিয়ার বিকল্প পথ দেয় এবং forward ও reverse উভয় পথের activation energy কমায়।','সাম্য অবস্থার thermodynamic অবস্থান ও K তাপমাত্রা-নির্ভর; catalyst কেবল equilibrium দ্রুত প্রতিষ্ঠা করে।','K = k_forward/k_reverse (নির্দিষ্ট তাপমাত্রায়)','অনুঘটক যোগ করলে উৎপাদের সাম্য-পরিমাণ বাড়ে—এ ধারণা ভুল।','শিল্পে catalyst উৎপাদন হার বাড়ায়, কিন্তু equilibrium yield নিজে থেকে বদলায় না।',['সাম্য ও kinetics আলাদা করো।','দুই দিকের activation barrier কমা দেখো।','K অপরিবর্তিত নির্ণয় করো।']),
    make('chem1-04',12,'scenario',4,'একটি উষ্মাক্ষেপী সাম্য বিক্রিয়ায় তাপমাত্রা বাড়ালে সাম্য কোন দিকে সরে?',['উৎপাদের দিকে','বিক্রিয়কের দিকে','কোনো পরিবর্তন নেই','সব পদার্থ গ্যাসে পরিণত হয়'],1,'উষ্মাক্ষেপী বিক্রিয়ায় তাপকে উৎপাদ হিসেবে ভাবা যায়। তাপমাত্রা বাড়ানো হলে সাম্য অতিরিক্ত তাপ কমাতে বিপরীত দিকে সরে।','Le Chatelier নীতি অনুযায়ী চাপ বা ঘনমাত্রার প্রভাব থেকে তাপমাত্রার প্রভাব আলাদা করে বিচার করতে হয়।','উষ্মাক্ষেপী: Reactants ⇌ Products + heat','তাপ বাড়লে সব রাসায়নিক সাম্য উৎপাদমুখী হয় না।','শিল্প-প্রক্রিয়ায় তাপমাত্রা yield ও reaction rate-এর মধ্যে trade-off তৈরি করে।',['বিক্রিয়ার তাপীয় প্রকৃতি শনাক্ত করো।','তাপকে উৎপাদ পাশে রাখো।','বাড়তি তাপের বিরোধী দিকে সাম্য সরাও।']),
    make('chem1-05',4,'process',2,'Haber প্রক্রিয়ায় অ্যামোনিয়া উৎপাদনের সাম্য বিক্রিয়া কোনটি?',['N₂ + O₂ ⇌ 2NO','N₂ + 3H₂ ⇌ 2NH₃','2SO₂ + O₂ ⇌ 2SO₃','CO₂ + H₂O ⇌ H₂CO₃'],1,'Haber প্রক্রিয়ায় nitrogen ও hydrogen থেকে ammonia তৈরি হয়। বিক্রিয়াটি উষ্মাক্ষেপী ও গ্যাসীয় মোল সংখ্যা কমায়।','শিল্পে উপযুক্ত চাপ, তাপমাত্রা ও iron-based catalyst ব্যবহার করা হয়; নির্দিষ্ট অপারেটিং শর্ত plant অনুযায়ী নির্ধারিত।','N₂(g) + 3H₂(g) ⇌ 2NH₃(g) + heat','Haber প্রক্রিয়াকে SO₂ থেকে SO₃ তৈরির Contact process-এর সঙ্গে গুলিয়ে ফেলো না।','সারের কাঁচামাল ammonia শিল্পে উৎপাদিত হয়।',['নাইট্রোজেন ও হাইড্রোজেন reagent শনাক্ত করো।','পরমাণু ভারসাম্য করো।','2NH₃ উৎপাদ লিখো।']),
    make('chem1-05',9,'process',3,'Contact process-এ SO₂ থেকে SO₃ তৈরিতে প্রধান অনুঘটক কোনটি?',['Fe','V₂O₅','Ni','Pt black only'],1,'Contact process-এ vanadium(V) oxide, V₂O₅ সাধারণত catalyst হিসেবে ব্যবহৃত হয়।','প্রতিক্রিয়া reversible ও exothermic; catalyst rate বাড়ায়, equilibrium constant বদলায় না।','2SO₂ + O₂ ⇌ 2SO₃','Haber process-এর iron catalyst-কে Contact process-এ সরাসরি বসানো সঠিক নয়।','সালফিউরিক অ্যাসিড উৎপাদনে Contact process ব্যবহৃত হয়।',['উৎপাদ SO₃ শনাক্ত করো।','শিল্প প্রক্রিয়ার catalyst মনে করো।','V₂O₅ নির্বাচন করো।']),
    // Chemistry — Second paper (5 chapters)
    make('chem2-01',2,'interpretation',2,'জলাশয়ের পানিতে BOD অনেক বেড়ে গেলে সাধারণত কী আশঙ্কা করা হয়?',['দ্রবীভূত অক্সিজেন কমতে পারে','পানির তাপমাত্রা শূন্য হয়','সব জীবাণু সঙ্গে সঙ্গে মরে','লবণাক্ততা অবশ্যই শূন্য হয়'],0,'Biochemical Oxygen Demand হলো জৈব পদার্থ ভাঙতে অণুজীবের প্রয়োজনীয় dissolved oxygen-এর পরিমাণ।','BOD বেশি হলে অণুজীব বেশি অক্সিজেন ব্যবহার করতে পারে, ফলে মাছসহ জলজ প্রাণীর জন্য dissolved oxygen কমে যেতে পারে।','BOD = নির্দিষ্ট সময়ে জৈবিক জারণে ব্যবহৃত O₂-এর পরিমাণ','BOD বেশি মানেই পানিতে অক্সিজেন বেশি—এটি উল্টো ধারণা।','নর্দমা ও খাদ্যশিল্পের বর্জ্য জলাশয়ে গেলে BOD বাড়তে পারে।',['জৈব বর্জ্য বাড়ার প্রভাব ভাবো।','অণুজীবের oxygen consumption শনাক্ত করো।','DO কমার ঝুঁকি নির্ণয় করো।']),
    make('chem2-01',7,'causeEffect',2,'অ্যাসিড বৃষ্টির প্রধান precursor gas কোন জোড়া?',['SO₂ ও NOₓ','O₂ ও N₂','He ও Ne','H₂ ও CH₄ only'],0,'বায়ুমণ্ডলে SO₂ ও nitrogen oxides অক্সিডাইজ হয়ে পানির সঙ্গে sulfuric ও nitric acid তৈরি করতে পারে।','এসব গ্যাসের উৎসে জীবাশ্ম জ্বালানি পোড়ানো ও কিছু শিল্পপ্রক্রিয়া রয়েছে।','SO₂ → H₂SO₄; NOₓ → HNO₃ (সামগ্রিক পথ)','অ্যাসিড বৃষ্টি শুধু CO₂ দ্রবীভূত হওয়ার ফল নয়; CO₂ স্বাভাবিক বৃষ্টিকে সামান্য অম্লীয় করে, কিন্তু অ্যাসিড বৃষ্টির প্রধান কারণ SO₂/NOₓ।','অ্যাসিড বৃষ্টি মাটি, জলজ পরিবেশ ও স্থাপনা ক্ষতিগ্রস্ত করতে পারে।',['SO₂ ও NOₓ উৎস চিহ্নিত করো।','বায়ুমণ্ডলে অক্সিডেশন ও hydration বিবেচনা করো।','অ্যাসিড গঠনের ফল নির্ণয় করো।']),
    make('chem2-02',1,'analytical',2,'একটি অজানা carbonyl যৌগ Tollens reagent-এ silver mirror দেয়। যৌগটি সবচেয়ে সম্ভাব্য কোন শ্রেণির?',['Aldehyde','সাধারণ ketone','Alkane','Ether'],0,'সাধারণ aldehyde Tollens reagent-কে reduce করে ধাতব silver তৈরি করতে পারে; নিজে carboxylate-এ oxidize হয়।','সাধারণ ketone সাধারণত এই পরীক্ষায় silver mirror দেয় না, তবে কিছু বিশেষ reducing compounds ব্যতিক্রম হতে পারে।','R–CHO + [O] → R–COOH','সব carbonyl compound একইভাবে Tollens test দেয় না।','জৈব যৌগের functional group শনাক্তে qualitative test ব্যবহৃত হয়।',['Tollens test-এর observation পড়ো।','Aldehyde-এর সহজ oxidation বোঝো।','Aldehyde নির্বাচন করো।']),
    make('chem2-02',7,'conceptual',4,'বেনজিনে সাধারণ electrophilic substitution reaction addition-এর চেয়ে বেশি অনুকূল কেন?',['Substitution-এর পর aromaticity পুনঃপ্রতিষ্ঠিত থাকে','Addition-এ সবসময় বেশি শক্তি বের হয়','বেনজিনে π electron নেই','Substitution-এ ring ভেঙে যায়'],0,'বেনজিনের aromatic stabilization শক্তিশালী। Electrophilic substitution-এ সাময়িক aromaticity হারালেও proton অপসারণের পর aromatic ring ফিরে আসে।','Addition স্থায়ীভাবে aromatic π-system নষ্ট করে; তাই সাধারণ শর্তে substitution তুলনামূলক অনুকূল।','C₆H₆ + E⁺ → [σ-complex] → C₆H₅E + H⁺','বেনজিনকে তিনটি বিচ্ছিন্ন alkene bond হিসেবে বিবেচনা করলে aromaticity বোঝা যায় না।','বেনজিনের nitration ও halogenation শিল্পে গুরুত্বপূর্ণ।',['Aromatic stabilization চিহ্নিত করো।','দুই reaction pathway তুলনা করো।','aromaticity পুনরুদ্ধারের সুবিধা শনাক্ত করো।']),
    make('chem2-03',0,'multiStep',2,'N₂ + 3H₂ → 2NH₃ বিক্রিয়ায় ১ mol N₂-এর জন্য পর্যাপ্ত H₂ থাকলে সর্বোচ্চ কত mol NH₃ তৈরি হবে?',['১ mol','২ mol','৩ mol','৬ mol'],1,'সমীকরণের mole ratio অনুযায়ী ১ mol N₂ থেকে ২ mol NH₃ তৈরি হয়।','সুষম সমীকরণের সহগই stoichiometric ratio নির্দেশ করে।','1 mol N₂ : 2 mol NH₃','৩ mol H₂ থাকলেই ৩ mol NH₃ হবে না; coefficient ratio 3:2।','সার উৎপাদনে stoichiometry দিয়ে কাঁচামালের পরিমাণ নির্ধারণ হয়।',['সমীকরণ সুষম আছে যাচাই করো।','N₂ ও NH₃-এর সহগ তুলনা করো।','১×২ = ২ mol হিসাব করো।']),
    make('chem2-03',9,'mathematical',2,'১.0 M দ্রবণ থেকে ১০০ mL ০.২০ M দ্রবণ তৈরি করতে stock solution কত mL লাগবে?',['১০ mL','২০ mL','৫০ mL','৮০ mL'],1,'Dilution-এ দ্রবিত পদার্থের mole অপরিবর্তিত থাকে। তাই M₁V₁ = M₂V₂।','V₁ = (0.20×100)/1.0 = 20 mL; পরে solvent দিয়ে final volume 100 mL করতে হবে।','M₁V₁ = M₂V₂','২০ mL stock নিয়ে ১০০ mL পানি যোগ মানেই final ১২০ mL নয়; final volume ১০০ mL করতে হবে।','ল্যাবে নির্দিষ্ট molarity-র standard solution তৈরি হয় volumetric flask-এ।',['M₁, M₂ ও V₂ লিখো।','V₁ = M₂V₂/M₁ বসাও।','২০ mL stock নাও এবং final volume ১০০ mL করো।']),
    make('chem2-04',3,'conceptual',2,'একটি galvanic cell-এ বাহ্যিক তারে electron কোন দিক দিয়ে প্রবাহিত হয়?',['Cathode থেকে anode','Anode থেকে cathode','Salt bridge থেকে electrode','দুই electrode থেকেই বাইরে'],1,'Galvanic cell-এ anode-এ oxidation ঘটে এবং electron উৎপন্ন হয়। বাহ্যিক current path-এ electron anode থেকে cathode-এ যায়।','Cathode-এ reduction ঘটে; salt bridge ion চলাচল দিয়ে charge neutrality বজায় রাখে।','Anode: oxidation; Cathode: reduction','প্রচলিত current ও electron flow-এর দিক এক নয়; conventional current বিপরীত দিকে।','ব্যাটারির electrochemical energy বৈদ্যুতিক শক্তিতে রূপান্তরিত হয়।',['Oxidation electrode শনাক্ত করো।','Electron উৎপন্ন হওয়ার স্থান চিহ্নিত করো।','বাহ্যিক বর্তনীতে anode → cathode দিক লেখো।']),
    make('chem2-04',8,'experiment',4,'Cu²⁺ দ্রবণ থেকে copper electrodeposition-এ একই current ও সময় দ্বিগুণ করলে Faraday-এর সূত্র অনুযায়ী জমা Cu-এর ভর কী হবে?',['অর্ধেক','দ্বিগুণ','চার গুণ','অপরিবর্তিত'],1,'ইলেক্ট্রোলাইসিসে জমা ভর m ∝ It; electrochemical equivalent স্থির থাকলে current-time product দ্বিগুণে ভর দ্বিগুণ।','এখানে Cu²⁺ + 2e⁻ → Cu, তাই charge-এর সঙ্গে deposited amount-এর নির্দিষ্ট সম্পর্ক রয়েছে।','m = ZIt','সময় দ্বিগুণ করলে ভর অর্ধেক হয় না; charge It দ্বিগুণ হয়।','Electroplating-এ আবরণের ভর নিয়ন্ত্রণে Faraday law ব্যবহৃত হয়।',['m = ZIt লেখো।','I অপরিবর্তিত এবং t→2t বসাও।','m→2m নির্ণয় করো।']),
    make('chem2-05',8,'process',2,'বর্জ্যপানি পরিশোধনে বড় কঠিন বর্জ্য অপসারণের প্রাথমিক ধাপ কোনটি?',['Screening','Chlorination','Reverse osmosis শেষে','পানি ফুটানো'],0,'প্রাথমিক wastewater treatment-এ screen দিয়ে বড় কঠিন বস্তু ও আবর্জনা সরানো হয়।','এরপর grit removal ও sedimentation-এর মতো ধাপ থাকতে পারে; treatment train-এর ক্রম প্ল্যান্টভেদে বদলায়।','সাধারণ ধারা: screening → grit removal → primary settling → secondary treatment','Chlorination বড় কঠিন বর্জ্য সরানোর ধাপ নয়; এটি জীবাণুনাশে ব্যবহৃত হয়।','পৌর বর্জ্যপানি শোধনাগারে screening downstream equipment রক্ষা করে।',['বর্জ্যের আকার বিবেচনা করো।','বড় বস্তু প্রথমে আলাদা করো।','screening নির্বাচন করো।']),
    make('chem2-05',5,'realWorld',2,'অ্যালুমিনিয়াম পুনর্ব্যবহার (recycling) নতুন আকরিক থেকে উৎপাদনের তুলনায় সাধারণত কম শক্তি লাগে কেন?',['ধাতুতে পরমাণু থাকে না','ধাতু পুনরায় গলানো/প্রক্রিয়াকরণে আকরিক থেকে electrolysis-এর প্রয়োজন এড়ানো যায়','অ্যালুমিনিয়াম জ্বলে যায়','পুনর্ব্যবহারে কোনো তাপ লাগে না'],1,'বক্সাইট থেকে প্রাথমিক অ্যালুমিনিয়াম উৎপাদনে শক্তি-নিবিড় electrolysis প্রয়োজন। পুনর্ব্যবহারে পরিষ্কার scrap গলিয়ে পরিশোধন করলেই চলে।','অবশ্যই sorting, contamination removal ও remelting লাগে; তবে সাধারণত primary production-এর তুলনায় শক্তি কম লাগে।','Primary Al: ore refining + electrolysis; secondary Al: sorting + remelting','Recycling একেবারে শক্তিহীন নয়; শুধু তুলনামূলক কম শক্তি লাগে।','অ্যালুমিনিয়াম ক্যান পুনর্ব্যবহার সম্পদ ও শক্তি সাশ্রয় করে।',['Primary production-এর ধাপগুলো ভাবো।','Scrap পুনর্গলানোর পথের সঙ্গে তুলনা করো।','electrolysis এড়ানোর শক্তি সাশ্রয় নির্ণয় করো।']),
    // Higher Mathematics — First paper (10 chapters)
    make('math1-01',1,'mathematical',2,'একটি ২×২ ম্যাট্রিক্সের determinant শূন্য নয়। কী সিদ্ধান্ত নেওয়া যায়?',['ম্যাট্রিক্সটি singular','ম্যাট্রিক্সটির inverse আছে','ম্যাট্রিক্সটি অবশ্যই symmetric','সব উপাদান শূন্য'],1,'Square matrix-এর determinant nonzero হলে matrix nonsingular এবং inverse বিদ্যমান।','det(A) ≠ 0 হলে A⁻¹ = adj(A)/det(A)।','A⁻¹ exists ⇔ det(A) ≠ 0','determinant শূন্য হলে inverse থাকে—এটি ভুল।','Linear system সমাধানে inverse matrix ব্যবহৃত হয়।',['determinant-এর মান দেখো।','শূন্য নয় নিশ্চিত করো।','inverse-এর existence শর্ত প্রয়োগ করো।']),
    make('math1-01',8,'conceptual',2,'কোনো square matrix-এর determinant শূন্য হলে সেটিকে কী বলা হয়?',['Identity','Singular','Orthogonal','Diagonal only'],1,'det(A)=0 হলে matrix singular; এর row বা column linear dependent।','এ কারণে inverse matrix থাকে না এবং সংশ্লিষ্ট homogeneous system-এর non-trivial solution থাকতে পারে।','det(A)=0 ⇒ A singular','সব singular matrix-এর প্রতিটি উপাদান শূন্য নয়।','ম্যাট্রিক্স সমীকরণে uniqueness পরীক্ষা করতে singularity গুরুত্বপূর্ণ।',['determinant যাচাই করো।','শূন্য হলে singular বলো।','inverse না থাকার সিদ্ধান্ত নাও।']),
    make('math1-02',7,'conceptual',2,'দুটি ভেক্টরের cross product-এর মান কী জ্যামিতিক পরিমাণ নির্দেশ করে?',['তাদের মধ্যবর্তী আয়তন','সমান্তর চতুর্ভুজের ক্ষেত্রফল','তাদের দূরত্বের যোগফল','ডট গুণফল'],1,'|A×B| = |A||B|sinθ এবং এটি A ও B দ্বারা গঠিত parallelogram-এর ক্ষেত্রফল।','ত্রিভুজের ক্ষেত্রফল হলে অর্ধেক নিতে হয়।','Area = |A×B|','Cross product-এর মান scalar হলেও cross product নিজে একটি vector।','টর্কের মানও |r×F|; lever arm ও বলের ভূমিকা বোঝায়।',['দুটি ভেক্টরকে বাহু ধরো।','লম্ব উপাংশের কারণে ক্ষেত্রফল গঠিত হয়।','|A×B| প্রয়োগ করো।']),
    make('math1-02',9,'mathematical',3,'A = (2,0) এবং B = (0,3) হলে A·B কত?',['০','৫','৬','১২'],0,'ডট গুণফল সমান corresponding components-এর গুণফলের যোগফল।','2×0 + 0×3 = 0; দুটি ভেক্টর পরস্পর লম্ব।','A·B = AₓBₓ + AᵧBᵧ','দুটি ভেক্টরের মান 2 ও 3 বলে dot product সবসময় 6 নয়; কোণও প্রয়োজন।','বল ও সরণের dot product থেকে কাজ নির্ণয় হয়।',['উপাংশ লিখো।','উপাংশভিত্তিক গুণফল যোগ করো।','0+0=0।']),
    make('math1-03',5,'analytical',2,'দুটি অশূন্য সরলরেখার ঢাল m₁ ও m₂ হলে তারা পরস্পর লম্ব হওয়ার শর্ত কোনটি?',['m₁=m₂','m₁m₂=−1','m₁+m₂=0 সবসময়','m₁m₂=1'],1,'দুটি অশূন্য, সসীম ঢালবিশিষ্ট রেখার perpendicularity-তে ঢালের গুণফল −1।','উল্লম্ব ও অনুভূমিক রেখার ক্ষেত্রে একটি ঢাল অসংজ্ঞায়িত; সেই বিশেষ ক্ষেত্রে আলাদাভাবে বিচার করতে হয়।','m₁m₂ = −1','এই শর্ত parallel রেখার নয়; parallel হলে m₁=m₂।','সমকোণী স্থাপত্য ও coordinate geometry-তে রেখার লম্বতা ব্যবহৃত হয়।',['দুটি রেখার ঢাল শনাক্ত করো।','লম্বতার শর্ত লেখো।','গুণফল −1 যাচাই করো।']),
    make('math1-03',2,'mathematical',2,'x/a + y/b = 1 সরলরেখার x-অক্ষছেদ ও y-অক্ষছেদ কোন জোড়া?',['(a,0) ও (0,b)','(0,a) ও (b,0)','(a,b) ও (0,0)','(−a,0) ও (0,−b)'],0,'Intercept form-এ y=0 দিলে x=a এবং x=0 দিলে y=b।','অতএব রেখাটি অক্ষদ্বয়কে যথাক্রমে a ও b বিন্দুতে ছেদ করে (যেখানে a,b শূন্য নয়)।','x/a + y/b = 1','a ও b হলো ঢাল নয়; এগুলো অক্ষছেদ।','জমির মাপজোখ বা graph plotting-এ intercept form সুবিধাজনক।',['y=0 বসাও।','x=a পাও।','x=0 বসিয়ে y=b পাও।']),
    make('math1-04',3,'analytical',2,'বৃত্তের কোনো স্পর্শবিন্দুতে স্পর্শক ও ব্যাসার্ধের মধ্যবর্তী কোণ কত?',['০°','৪৫°','৯০°','১৮০°'],2,'বৃত্তের স্পর্শক স্পর্শবিন্দুতে ব্যাসার্ধের লম্ব।','ব্যাসার্ধ কেন্দ্র থেকে স্পর্শবিন্দুতে যায়; স্পর্শক ঐ বিন্দুতে বৃত্তের স্থানীয় দিক।','OT ⟂ tangent at T','স্পর্শক কেন্দ্র দিয়ে যায়—এটি ব্যাসার্ধের রেখা নয়।','চাকা ও বৃত্তাকার gear-এর tangent geometry-তে এটি ব্যবহৃত হয়।',['কেন্দ্র O ও স্পর্শবিন্দু T চিহ্নিত করো।','OT ব্যাসার্ধ আঁকো।','স্পর্শকের সঙ্গে 90° কোণ লেখো।']),
    make('math1-04',5,'mathematical',3,'x²+y²−6x+8y+9=0 বৃত্তের কেন্দ্র ও ব্যাসার্ধ কত?',['(3,−4), 4','(−3,4), 4','(3,−4), 16','(−3,4), 16'],0,'পূর্ণবর্গে x²−6x + y²+8y +9=0 ⇒ (x−3)²+(y+4)²=16।','কেন্দ্র (3,−4), r=√16=4।','(x−h)²+(y−k)²=r²','ধ্রুবক পদকে সরাসরি ব্যাসার্ধ ধরে নেওয়া যাবে না।','বৃত্তাকার পথ বা locus নির্ণয়ে standard form ব্যবহৃত হয়।',['x ও y-তে পূর্ণবর্গ করো।','সমীকরণ standard form-এ আনো।','কেন্দ্র ও r পড়ো।']),
    make('math1-05',2,'conceptual',2,'৫টি ভিন্ন বই থেকে ২টি বেছে নেওয়ার ক্ষেত্রে ক্রম গুরুত্বপূর্ণ না হলে কোন গণনা ব্যবহার করতে হবে?',['Permutation','Combination','Factorial sum','Matrix'],1,'বাছাইয়ে শুধু কোন দুটি বই নেওয়া হয়েছে তা গুরুত্বপূর্ণ; তাদের ক্রম গুরুত্বপূর্ণ নয়।','তাই combination ব্যবহার: 5C2 = 10।','ⁿCᵣ = n!/[r!(n−r)!]','Permutation-এ ক্রম গুরুত্বপূর্ণ; এখানে তা নয়।','কমিটি নির্বাচন ও উপদল গঠনে combination ব্যবহৃত হয়।',['কাজটি বাছাই নাকি সাজানো নির্ধারণ করো।','ক্রম অপ্রাসঙ্গিক হওয়ায় combination নাও।','5C2 হিসাব করো।']),
    make('math1-05',4,'mathematical',2,'A, B, C, D চারটি ভিন্ন অক্ষর প্রতিটি একবার করে ব্যবহার করে কয়টি ৪-অক্ষরের বিন্যাস করা যায়?',['১২','১৬','২৪','৪৮'],2,'চারটি স্বতন্ত্র অক্ষর সবগুলো সাজানোর সংখ্যা 4!।','প্রথম স্থানের জন্য ৪টি, দ্বিতীয়টির জন্য ৩টি, তৃতীয়টির জন্য ২টি এবং শেষটির জন্য ১টি বিকল্প থাকে; গুণের নীতি প্রয়োগ করলে ২৪টি বিন্যাস পাওয়া যায়।','⁴P₄ = 4! = 24','৪টি অক্ষর থেকে ৪টি বেছে নেওয়া combination 1 হলেও arrangement আলাদা প্রশ্ন।','পাসকোড বা ভিন্ন ক্রমের সাজানোতে permutation ধারণা লাগে।',['প্রথম স্থানে ৪টি পছন্দ।','পরের স্থানে ৩, তারপর ২, শেষে ১।','গুণ করে ২৪ পাও।']),
    make('math1-06',6,'conceptual',2,'1 + tan²θ কোন পরিচয়ের সমান?',['sec²θ','cosec²θ','sin²θ','cot²θ'],0,'মৌলিক ত্রিকোণমিতিক পরিচয় থেকে sin²θ+cos²θ=1। cos²θ দিয়ে ভাগ করলে 1+tan²θ=sec²θ।','পরিচয়টি cosθ ≠ 0 হলে সরাসরি ভাগ করে পাওয়া যায়।','1 + tan²θ = sec²θ','এটি 1+cot²θ=cosec²θ পরিচয়ের সঙ্গে গুলিয়ে ফেলো না।','ত্রিকোণমিতিক সমীকরণ সরলীকরণে পরিচয় ব্যবহৃত হয়।',['sin²+cos²=1 লেখো।','cos² দিয়ে ভাগ করো।','tan ও sec-এর অনুপাত বসাও।']),
    make('math1-06',7,'mathematical',2,'θ প্রথম চতুর্ভাগে এবং sinθ = 3/5 হলে cosθ কত?',['৩/৫','৪/৫','৫/৪','−৪/৫'],1,'sin²θ+cos²θ=1। তাই cos²θ=1−9/25=16/25।','প্রথম চতুর্ভাগে cosθ ধনাত্মক, তাই cosθ=4/5।','cosθ = +√(1−sin²θ) = 4/5','চতুর্ভাগ না জানলে cos-এর চিহ্ন নিশ্চিত করা যায় না।','ত্রিভুজভিত্তিক মডেলে অনুপাত দিয়ে অজানা বাহু নির্ণয় করা যায়।',['পরিচয় প্রয়োগ করো।','cos²θ=16/25 পাও।','প্রথম চতুর্ভাগের জন্য ধনাত্মক মূল নাও।']),
    make('math1-07',2,'conceptual',2,'sin(90°−θ) কোনটির সমান?',['sinθ','cosθ','tanθ','−cosθ'],1,'Complementary angle identity অনুযায়ী sin(90°−θ)=cosθ।','একটি সমকোণী ত্রিভুজে θ-এর বিপরীত বাহু অন্য কোণের সন্নিহিত বাহু হয়।','sin(90°−θ) = cosθ','sin(90°−θ) = sinθ নয়; complementary angle-এ cofunction বদলায়।','উচ্চতা ও দূরত্বের সমস্যায় complementary angle ব্যবহৃত হয়।',['দুটি কোণের যোগ 90° নিশ্চিত করো।','cofunction identity প্রয়োগ করো।','cosθ লিখো।']),
    make('math1-07',5,'mathematical',3,'cos2θ-এর একটি সঠিক সমতুল্য রূপ কোনটি?',['2sinθcosθ','cos²θ−sin²θ','1+2sin²θ','sin²θ−cos²θ'],1,'Cosine double-angle identity তিনভাবে লেখা যায়: cos²θ−sin²θ, 2cos²θ−1 অথবা 1−2sin²θ।','প্রথম রূপটি সরাসরি cosine addition formula থেকে আসে।','cos2θ = cos²θ − sin²θ','2sinθcosθ হলো sin2θ; cosine double-angle নয়।','ত্রিকোণমিতিক সমীকরণ ও পর্যাবৃত্ত সংকেতে এ পরিচয় কাজে লাগে।',['cos(θ+θ) লেখো।','cos(A+B) সূত্র প্রয়োগ করো।','cos²θ−sin²θ পাও।']),
    make('math1-08',1,'conceptual',2,'একটি one-to-one function-এর inverse সম্পর্কে কোন বক্তব্য সঠিক?',['Inverse সবসময় relation-ই থাকে, function নয়','One-to-one হলে inverse-ও function','Function-এর inverse সবসময় একই function','Domain-এর কোনো ভূমিকা নেই'],1,'একটি function-এর inverse একটি function হতে হলে মূল function injective (one-to-one) হতে হয়।','Horizontal line test দিয়ে graph-এ one-to-one যাচাই করা যায়।','f(a)=f(b) ⇒ a=b','সব function-এর inverse function থাকে—এটি ভুল; injectivity প্রয়োজন।','Encryption-এর reversible mapping-এ one-to-one mapping গুরুত্বপূর্ণ।',['একই output-এর জন্য একাধিক input আছে কি দেখো।','Injective হলে horizontal line test পাস করে।','তখন inverse function হয়।']),
    make('math1-08',7,'mathematical',2,'বাস্তব সংখ্যায় f(x)=√(x−3)-এর domain কী?',['x<3','x≥3','সব বাস্তব x','x≤−3'],1,'বর্গমূলের ভিতরের রাশি বাস্তব হলে ঋণাত্মক হতে পারে না।','বর্গমূলের ভেতরের রাশি বাস্তব সংখ্যায় অঋণাত্মক হতে হবে। তাই x−3≥0 সমাধান করলে x≥3 পাওয়া যায়; যেকোনো মূলদ রাশির domain নির্ধারণে এই শর্ত আগে যাচাই করতে হয়।','Domain condition: x−3 ≥ 0','বর্গমূলের বাইরে থাকা x-কে শূন্য বা ঋণাত্মক হওয়া থেকে আটকাতে হয় না; শুধু radicand শর্তযুক্ত।','ফাংশনের domain নির্ধারণে algebraic restriction গুরুত্বপূর্ণ।',['radicand শনাক্ত করো।','x−3≥0 সমাধান করো।','[3,∞) domain লেখো।']),
    make('math1-09',2,'conceptual',2,'কোনো differentiable function-এর স্থানীয় extremum x=c-তে ঘটলে সাধারণ interior-point শর্ত কী?',['f′(c)=0','f(c)=0','f″(c)=0 সবসময়','f′(c)=1'],0,'Differentiable function-এর interior local maximum/minimum-এ Fermat theorem অনুযায়ী derivative শূন্য।','এটি প্রয়োজনীয় শর্ত, যথেষ্ট নয়; derivative শূন্য হলেও inflection বা flat point হতে পারে।','f′(c)=0 (প্রয়োজনীয় শর্ত)','f′(c)=0 হলেই local maximum/minimum নিশ্চিত—এটি ভুল।','লাভ-ক্ষতি বা সর্বনিম্ন উপকরণ ব্যবহারের সমস্যা optimization দিয়ে সমাধান হয়।',['স্থানীয় extremum ও interior point নিশ্চিত করো।','differentiable শর্ত প্রয়োগ করো।','f′(c)=0 লিখো।']),
    make('math1-09',9,'mathematical',4,'f(x)=x²−4x+1 হলে x=3-এ derivative কত?',['০','২','৪','৬'],1,'Power rule অনুসারে f′(x)=2x−4।','x=3 বসালে f′(3)=6−4=2।','d(xⁿ)/dx = nxⁿ⁻¹','f(3) এবং f′(3) একই জিনিস নয়; একটি function value, অন্যটি slope।','চলমান বস্তুর অবস্থান ফাংশনের derivative থেকে তাৎক্ষণিক বেগ পাওয়া যায়।',['প্রতিটি term differentiate করো।','f′(x)=2x−4 লেখো।','x=3 বসিয়ে 2 পাও।']),
    make('math1-10',1,'conceptual',2,'Definite integral ∫ₐᵇ f(x)dx সরাসরি কী নির্দেশ করে?',['সবসময় geometric area-এর ধনাত্মক মান','signed accumulation/area','শুধু curve-এর slope','শুধু interval-এর দৈর্ঘ্য'],1,'Definite integral interval-এ function-এর signed accumulation নির্দেশ করে। x-axis-এর নিচের অংশ ঋণাত্মক অবদান রাখে।','geometric total area চাইলে axis-এর নিচের অংশের absolute area আলাদা করে যোগ করতে হয়।','∫ₐᵇ f(x)dx = F(b)−F(a)','Definite integral সবসময় area-এর ধনাত্মক মান—এটি ভুল।','বেগ-সময় গ্রাফের integral displacement দেয়।',['interval ও function চিহ্নিত করো।','x-axis-এর ওপরে/নিচের sign বিবেচনা করো।','signed integral নির্ণয় করো।']),
    make('math1-10',6,'mathematical',2,'∫₀² 3x² dx-এর মান কত?',['৪','৬','৮','১২'],2,'3x²-এর antiderivative x³। সীমা বসিয়ে 2³−0³ = 8।','Fundamental theorem of calculus অনুযায়ী antiderivative-এর upper ও lower value-এর পার্থক্য নিতে হয়।','∫ 3x² dx = x³ + C; [x³]₀² = 8','ইন্টেগ্রাল করার পর constant C নির্দিষ্ট definite integral-এ বাদ যায়।','সময়ের সঙ্গে পরিবর্তিত হার থেকে মোট পরিমাণ পেতে integration ব্যবহৃত হয়।',['Antiderivative x³ লেখো।','উপরের সীমা ২ বসিয়ে ৮ পাও।','নিচের সীমা ০ বিয়োগ করো।']),
    // Higher Mathematics — Second paper (10 chapters)
    make('math2-01',0,'misconception',2,'কোনো অসমতা  −2 দিয়ে গুণ করলে অসমতার চিহ্নের কী হয়?',['একই থাকে','উল্টে যায়','সমীকরণ হয়ে যায়','শূন্য হয়'],1,'ঋণাত্মক সংখ্যা দিয়ে উভয় পক্ষ গুণ বা ভাগ করলে order reversal ঘটে।','যেমন 1<3, কিন্তু −2 দিয়ে গুণ করলে −2>−6।','a<b, c<0 ⇒ ac>bc','অসমতায় উভয় পাশে যেকোনো সংখ্যা দিয়ে গুণ করলেও চিহ্ন অপরিবর্তিত থাকে—এটি ভুল।','Linear inequality সমাধানে sign reversal খুব গুরুত্বপূর্ণ।',['গুণকের sign দেখো।','ঋণাত্মক হলে দুই পক্ষের ক্রম উল্টাও।','নতুন inequality লেখো।']),
    make('math2-01',6,'mathematical',2,'|x−2|<3 অসমতার সমাধান কোনটি?',['x<−1','−1<x<5','x>5','−5<x<1'],1,'Absolute inequality |A|<b (b>0) হলে −b<A<b।','−3<x−2<3; উভয় পাশে 2 যোগ করলে −1<x<5।','|x−2|<3 ⇔ −3<x−2<3','Absolute value সবসময় positive বলেই expression-এর ভিতরের রাশি positive—এটি ভুল।','Tolerance বা error range নির্ধারণে absolute inequality ব্যবহৃত হয়।',['Absolute value inequality-কে double inequality করো।','−3<x−2<3 লেখো।','২ যোগ করে interval বের করো।']),
    make('math2-02',1,'conceptual',2,'z = 3−4i হলে এর conjugate কোনটি?',['−3+4i','3+4i','−3−4i','4+3i'],1,'Complex conjugate-এ বাস্তব অংশ অপরিবর্তিত থাকে, কাল্পনিক অংশের sign উল্টায়।','অনুবন্ধী জটিল সংখ্যায় কাল্পনিক অংশের চিহ্ন বদলায়, কিন্তু বাস্তব অংশ অপরিবর্তিত থাকে। তাই 3−4i-এর অনুবন্ধী 3+4i।','z=a+bi ⇒ z̄=a−bi','Conjugate নিতে বাস্তব অংশের sign বদলায় না।','Complex arithmetic-এ denominator rationalize করতে conjugate ব্যবহৃত হয়।',['বাস্তব অংশ ৩ রাখো।','−4i-এর sign বদলাও।','3+4i লেখো।']),
    make('math2-02',8,'mathematical',3,'z=3+4i হলে |z| কত?',['৩','৪','৫','৭'],2,'Complex modulus হলো Argand plane-এ origin থেকে বিন্দুর দূরত্ব।','|z|=√(3²+4²)=√25=5।','|a+bi| = √(a²+b²)','Modulus-কে বাস্তব অংশ ও কাল্পনিক অংশের যোগফল ভাবা যাবে না।','AC impedance ও complex plane-এ magnitude নির্ণয়ে modulus ব্যবহৃত হয়।',['a=3,b=4 শনাক্ত করো।','√(a²+b²) ব্যবহার করো।','৫ পাও।']),
    make('math2-03',1,'conceptual',2,'ax²+bx+c=0 (a≠0)-এর দুই মূল α ও β হলে α+β কত?',['c/a','−b/a','b/a','−c/a'],1,'Quadratic equation-এর roots sum Vieta সূত্রে −b/a।','এটি factorization বা quadratic formula থেকে পাওয়া সম্পর্ক; মূল আলাদা না করেও যোগফল জানা যায়।','α+β = −b/a; αβ = c/a','মূলদ্বয়ের যোগফল −c/a নয়; −c/a হলো product-এর সঙ্গে sign-সংক্রান্ত ভুল।','Polynomial roots বিশ্লেষণে Vieta relation কাজে লাগে।',['সমীকরণ standard form-এ রাখো।','coefficient a ও b চিহ্নিত করো।','−b/a প্রয়োগ করো।']),
    make('math2-03',5,'analytical',2,'দ্বিঘাত সমীকরণে discriminant Δ=0 হলে বাস্তব মূল সম্পর্কে কী বলা যায়?',['দুটি ভিন্ন বাস্তব মূল','একটি দ্বিগুণ বাস্তব মূল','কোনো বাস্তব মূল নেই','দুটি জটিল conjugate মূল'],1,'Δ=b²−4ac শূন্য হলে quadratic formula-তে square-root term শূন্য হয়।','দুটি মূল সমান: x=−b/(2a)।','Δ = b²−4ac = 0 ⇒ α=β','Δ=0 মানে কোনো মূল নেই—এটি Δ<0-এর সঙ্গে গুলিয়ে ফেলা।','Parabola x-axis স্পর্শ করলে double root দেখা যায়।',['Δ হিসাব করো।','Δ=0 শর্ত প্রয়োগ করো।','একই root দুইবার আসে নির্ণয় করো।']),
    make('math2-04',3,'mathematical',4,'(x+2)⁵-এর বিস্তৃতিতে x³-এর সহগ কত?',['২০','৪০','৮০','১৬০'],1,'Binomial theorem-এ সাধারণ পদ Tᵣ₊₁ = ⁿCᵣ xⁿ⁻ʳ aʳ। x³ পেতে 5−r=3, তাই r=2।','সহগ = ⁵C₂ × 2² = 10×4=40।','⁵C₂·2² = 40','x³ পদের জন্য r=3 নেওয়া ভুল; exponent মিলিয়ে r=2।','বহুপদী বিস্তৃতি ও probability model-এ binomial coefficient ব্যবহৃত হয়।',['সাধারণ পদ লেখো।','x-এর ঘাত ৩ করতে r=২ নির্ণয় করো।','⁵C₂×2² হিসাব করো।']),
    make('math2-04',4,'pattern',2,'Pascal triangle-এ পরপর কোনো সারির অভ্যন্তরীণ সংখ্যা কীভাবে পাওয়া যায়?',['আগের সারির ঠিক ওপরের দুটি সংলগ্ন সংখ্যার যোগফল','আগের সারির সব সংখ্যার গুণফল','শুধু বাম পাশের সংখ্যা','সারি নম্বরের বর্গ'],0,'Pascal triangle-এর প্রতিটি interior entry তার ওপরের সারির দুই adjacent entry-এর যোগফল।','এই recurrence binomial coefficients-এর পরিচিতি C(n,r)=C(n−1,r−1)+C(n−1,r)-এর সঙ্গে মেলে।','ⁿCᵣ = ⁿ⁻¹Cᵣ₋₁ + ⁿ⁻¹Cᵣ','Pascal triangle-এর সংখ্যাগুলো এলোমেলো বা factorial ছাড়াই নির্ভরহীন নয়।','Binomial expansion-এর coefficient দ্রুত বের করতে Pascal triangle কাজে লাগে।',['উপরের সারির দুই পাশের entry দেখো।','দুটি যোগ করো।','নিচের সারির মাঝের entry বসাও।']),
    make('math2-05',0,'conceptual',4,'উপবৃত্তের যেকোনো বিন্দু থেকে দুই focus পর্যন্ত দূরত্বের যোগফল কী?',['পরিবর্তনশীল','2a ধ্রুব','2c ধ্রুব','শূন্য'],1,'Ellipse-এর সংজ্ঞা অনুযায়ী দুই focus থেকে দূরত্বের যোগফল ধ্রুব এবং major axis-এর দৈর্ঘ্য 2a।','Focus দুটির দূরত্ব 2c, কিন্তু বিন্দু থেকে focus-দ্বয়ের দূরত্বের যোগফল 2a।','PF₁ + PF₂ = 2a','2c হলো focus separation, focal distance sum নয়।','গ্রহের elliptical orbit ও উপবৃত্তাকার lens geometry-তে এই বৈশিষ্ট্য দেখা যায়।',['Ellipse-এর সংজ্ঞা স্মরণ করো।','দুটি focus থেকে দূরত্ব যোগ করো।','ধ্রুব 2a শনাক্ত করো।']),
    make('math2-05',2,'conceptual',2,'পরাবৃত্তের সংজ্ঞায় যেকোনো বিন্দুর focus ও directrix থেকে দূরত্বের সম্পর্ক কী?',['দূরত্বের যোগফল ধ্রুব','দূরত্ব দুটি সমান','focus দূরত্ব দ্বিগুণ','দূরত্বের গুণফল ধ্রুব'],1,'Parabola হলো এমন locus যেখানে প্রতিটি বিন্দুর focus থেকে দূরত্ব এবং directrix থেকে লম্ব দূরত্ব সমান।','এই সমদূরত্ব শর্ত থেকেই standard equation যেমন y²=4ax পাওয়া যায়।','PF = distance(P, directrix)','Ellipse-এর মতো parabola-তে দুই focus নেই; focus ও directrix ব্যবহৃত হয়।','Parabolic reflector-এ সমান্তরাল রশ্মি focus-এ মিলিত হয়।',['একটি point P নাও।','Focus থেকে PF মাপো।','Directrix থেকে perpendicular distance সমান করো।']),
    make('math2-06',1,'conceptual',2,'প্রধান branch-এ sin⁻¹x-এর মানের পরিসর কোনটি?',['−π/2 থেকে π/2','০ থেকে π','−π থেকে π','০ থেকে 2π'],0,'Inverse sine function-এর principal value range [−π/2, π/2]।','এই interval-এ sine one-to-one এবং পুরো [−1,1] range পায়।','sin⁻¹x ∈ [−π/2, π/2]','sin⁻¹x-কে 1/sin x ভাবা যাবে না; সেটি cosecant।','Inverse trigonometric function দিয়ে নির্দিষ্ট ratio থেকে principal angle পাওয়া যায়।',['sine-এর restricted domain দেখো।','যেখানে sine এক-এক, সেই interval নাও।','principal range লেখো।']),
    make('math2-06',7,'mathematical',3,'০°≤θ≤৩৬০° পরিসরে sinθ=1/2 হলে θ-এর সব সমাধান কোনটি?',['৩০° মাত্র','১৫০° মাত্র','৩০° ও ১৫০°','২১০° ও ৩৩০°'],2,'Reference angle 30°। Sine ধনাত্মক প্রথম ও দ্বিতীয় চতুর্ভাগে।','তাই θ=30° এবং 180°−30°=150°।','sinθ = 1/2 ⇒ θ = 30°, 150° (এই interval-এ)','শুধু calculator-এর principal angle নিয়ে interval-এর অন্য সমাধান বাদ দেওয়া যাবে না।','Periodic function-এর সমাধান নির্দিষ্ট interval অনুযায়ী enumerate করতে হয়।',['Reference angle 30° নির্ণয় করো।','Sine positive quadrant চিহ্নিত করো।','দুটি angle লেখো।']),
    make('math2-07',0,'conceptual',4,'সমতলে তিনটি অশূন্য, সমবিন্দুগামী ও অসমান্তরাল বল সাম্যাবস্থায় থাকলে Lami-এর উপপাদ্য কোন সম্পর্ক দেয়?',['F₁/sinα = F₂/sinβ = F₃/sinγ','F₁+F₂+F₃=1','F₁F₂=F₃','সব বল সমান'],0,'Lami-এর উপপাদ্য তিনটি coplanar, concurrent, non-parallel বলের equilibrium-এ প্রযোজ্য।','প্রতিটি বলের মান অপর দুই বলের মধ্যবর্তী কোণের sine-এর সমানুপাতিক।','F₁/sinα = F₂/sinβ = F₃/sinγ','যেকোনো সংখ্যক বা সমান্তরাল বলের ক্ষেত্রে Lami সরাসরি প্রয়োগ করা যায় না।','তিনটি cable দিয়ে ঝুলন্ত ভারের tension নির্ণয়ে এটি ব্যবহৃত হয়।',['তিনটি বল concurrent ও non-parallel কি না যাচাই করো।','প্রতিটি বলের বিপরীত angle নির্ধারণ করো।','Lami ratio লেখো।']),
    make('math2-07',5,'mathematical',2,'২০ N বলটি অনুভূমিকের সঙ্গে ৬০° কোণে প্রয়োগ করা হলে অনুভূমিক উপাংশ কত?',['১০ N','১০√৩ N','২০√৩ N','৪০ N'],0,'অনুভূমিক উপাংশ হলো Fcosθ।','20cos60° = 20×1/2 = 10 N।','Fₓ = F cosθ','sinθ দিয়ে অনুভূমিক উপাংশ নিতে গেলে কোণটি উল্লম্ব থেকে মাপা হয়েছে কি না দেখতে হবে।','বলকে উপাংশে ভেঙে equilibrium ও motion problem সমাধান করা হয়।',['কোণটি অনুভূমিক থেকে দেওয়া শনাক্ত করো।','Fcosθ নাও।','১০ N হিসাব করো।']),
    make('math2-08',2,'conceptual',2,'A-এর তুলনায় B-এর আপেক্ষিক বেগের ভেক্টর কোনটি?',['v_A−v_B','v_B−v_A','v_A+v_B সবসময়','শুধু বেগের মানের পার্থক্য'],1,'B-এর তুলনায় A বা A-এর তুলনায় B—কোন reference frame বলা হচ্ছে তা গুরুত্বপূর্ণ। A-এর তুলনায় B-এর আপেক্ষিক বেগ v_B−v_A।','একই reference frame-এ velocity vectors বিয়োগ করতে হয়; শুধু magnitudes বিয়োগ করলে সব ক্ষেত্রে সঠিক হয় না।','v_(B/A) = v_B − v_A','আপেক্ষিক বেগ নির্ণয়ে দিক উপেক্ষা করা যাবে না।','নদী পারাপার বা চলন্ত ট্রেন থেকে অন্য ট্রেনের গতি আপেক্ষিকভাবে দেখা হয়।',['পর্যবেক্ষক A নির্ধারণ করো।','বস্তুর বেগ থেকে পর্যবেক্ষকের বেগ বিয়োগ করো।','ভেক্টরের দিক রাখো।']),
    make('math2-08',3,'mathematical',2,'স্থির অবস্থা থেকে মুক্তভাবে পড়ন্ত বস্তুর ২ s পরে বেগ কত (g=9.8 m/s², বায়ুর বাধা নেই)?',['৪.৯ m/s নিচে','৯.৮ m/s নিচে','১৯.৬ m/s নিচে','৩৯.২ m/s নিচে'],2,'প্রাথমিক বেগ u=0 এবং ত্বরণ g। v=u+gt।','v=0+9.8×2=19.6 m/s নিচের দিকে।','v = u + gt','মুক্তপতনে বস্তু দুই সেকেন্ডে g মাত্র বেগ পায় না; প্রতিটি সেকেন্ডে g করে বাড়ে।','উচ্চতা থেকে ফেলা বস্তু ও নিরাপত্তা fall-time হিসাব এ সমীকরণ ব্যবহার হয়।',['u=0 লিখো।','g ও t বসাও।','v=19.6 m/s নিচে নির্ণয় করো।']),
    make('math2-09',1,'conceptual',4,'একটি bounded feasible polygonal region-এ linear programming-এর optimum কোথায় পাওয়া যায়?',['যেকোনো বক্ররেখায়','অন্তত একটি corner point-এ','শুধু origin-এ','শুধু boundary-এর মাঝখানে'],1,'Linear programming-এর objective function ও constraints linear। Feasible region bounded polygon হলে optimum কোনো vertex-এ পাওয়া যায়।','কিছু ক্ষেত্রে একাধিক adjacent vertex-সহ পুরো edge-এ একই optimum হতে পারে, কিন্তু vertex-এ মান পরীক্ষা করলেই optimum পাওয়া যায়।','Z = ax + by; constraints-এর feasible vertices পরীক্ষা','সব feasible problem bounded নয়; unbounded region-এ finite optimum নাও থাকতে পারে।','উৎপাদন পরিকল্পনায় সর্বোচ্চ লাভ/সর্বনিম্ন খরচ নির্ধারণে LP ব্যবহৃত হয়।',['Feasible region আঁকো।','সীমাবদ্ধ অঞ্চলের corner coordinate নির্ণয় করো।','প্রতিটি vertex-এ objective value হিসাব করো।']),
    make('math2-09',1,'analytical',2,'x≥0 এবং y≥0 শর্তসহ x+y≤4 অঞ্চলটি কোন চতুর্ভাগে অবস্থিত?',['শুধু প্রথম চতুর্ভাগ','শুধু দ্বিতীয় চতুর্ভাগ','তৃতীয় ও চতুর্থ','সব চতুর্ভাগ'],0,'x≥0 ও y≥0 উভয় শর্ত প্রথম চতুর্ভাগ ও অক্ষদ্বয়ের ওপর অঞ্চল সীমাবদ্ধ করে।','x+y≤4 রেখার নিচে থাকা অংশ প্রথম চতুর্ভাগে triangle-shaped feasible region।','x≥0, y≥0, x+y≤4','শুধু x+y≤4 দিলে চার চতুর্ভাগের অনেক বিন্দুও সম্ভব; non-negativity-র শর্ত অপরিহার্য।','Resource allocation-এ quantity সাধারণত negative হয় না, তাই x,y≥0 থাকে।',['প্রথমে x≥0 ও y≥0 থেকে quadrant নির্ণয় করো।','x+y=4 boundary আঁকো।','boundary-র নিচের অনুমোদিত অংশ ছায়া করো।']),
    make('math2-10',2,'conceptual',2,'প্রত্যেক পর্যবেক্ষণের সঙ্গে একই ধ্রুবক k যোগ করলে standard deviation কী হয়?',['k যোগ হয়','k বিয়োগ হয়','অপরিবর্তিত থাকে','k² দিয়ে গুণ হয়'],2,'সব data-তে একই ধ্রুবক যোগ করলে mean-ও k বাড়ে, কিন্তু প্রতিটি observation-এর mean থেকে বিচ্যুতি অপরিবর্তিত থাকে।','Variance ও standard deviation কেবল spread মাপে, absolute location নয়।','SD(X+k)=SD(X)','ধ্রুবক যোগ করলে data spread-ও একই পরিমাণ বাড়ে—এটি ভুল।','পরীক্ষার সব নম্বরে moderation bonus যোগ হলে SD অপরিবর্তিত থাকে।',['প্রতিটি x-কে x+k ধরো।','নতুন mean μ+k লেখো।','বিচ্যুতি (x+k)−(μ+k)=x−μ দেখাও।']),
    make('math2-10',6,'mathematical',2,'A ঘটনার সম্ভাবনা ০.৩ হলে A ঘটবে না—এর সম্ভাবনা কত?',['০.৩','০.৫','০.৭','১.৩'],2,'Complementary event-এর সম্ভাবনা মোট ১ থেকে মূল ঘটনার সম্ভাবনা বিয়োগ।','P(Aᶜ)=1−0.3=0.7।','P(Aᶜ)=1−P(A)','Complement probability মূল সম্ভাবনার সমান নয়, যদি না P(A)=0.5 হয়।','ঝুঁকি ও reliability হিসাব করতে complement rule ব্যবহৃত হয়।',['P(A) লিখো।','সম্পূর্ণ সম্ভাবনা ১ থেকে বিয়োগ করো।','০.৭ পাও।']),
    make('phy1-02',7,'assertion',3,'অভিকথন: দুটি অশূন্য ভেক্টর পরস্পর লম্ব হলে তাদের ডট গুণফল শূন্য। কারণ: ডট গুণফল A·B = |A||B|cosθ এবং θ = ৯০° হলে cosθ = ০।',['অভিকথন ও কারণ উভয়ই সত্য এবং কারণটি অভিকথনের সঠিক ব্যাখ্যা','অভিকথন ও কারণ উভয়ই সত্য, কিন্তু কারণটি সঠিক ব্যাখ্যা নয়','অভিকথন সত্য, কারণ মিথ্যা','অভিকথন মিথ্যা, কারণ সত্য'],0,'ডট গুণফল দুটি ভেক্টরের মান এবং তাদের মধ্যবর্তী কোণের cosine-এর গুণফল।','অশূন্য ভেক্টর লম্ব হলে θ=90°; তাই cosθ=0 এবং A·B=0। কারণটি অভিকথনকে সরাসরি ব্যাখ্যা করে।','A·B = |A||B|cos90° = 0','ডট গুণফল শূন্য হওয়ার একমাত্র কারণ ভেক্টরের একটি শূন্য হওয়া নয়; অশূন্য লম্ব ভেক্টরের ক্ষেত্রেও এটি শূন্য।','কাজ W=F·s-এ বল ও সরণ পরস্পর লম্ব হলে কাজ শূন্য হয়।',['অভিকথনে দেওয়া শর্ত শনাক্ত করো।','ডট গুণফলের সংজ্ঞায় θ=90° বসাও।','cos90°=0 থেকে কারণের যৌক্তিকতা যাচাই করো।']),
    make('chem1-03',4,'assertion',3,'অভিকথন: H₂O অণুর bond angle, NH₃ অণুর bond angle-এর চেয়ে ছোট। কারণ: H₂O-তে কেন্দ্রীয় O পরমাণুর দুটি lone pair থাকে, আর NH₃-তে N পরমাণুর একটি lone pair থাকে; lone pair–lone pair বিকর্ষণ তুলনামূলক বেশি।',['অভিকথন ও কারণ উভয়ই সত্য এবং কারণটি অভিকথনের সঠিক ব্যাখ্যা','অভিকথন ও কারণ উভয়ই সত্য, কিন্তু কারণটি সঠিক ব্যাখ্যা নয়','অভিকথন সত্য, কারণ মিথ্যা','অভিকথন মিথ্যা, কারণ সত্য'],0,'VSEPR মডেলে ইলেকট্রন-জোড়ার বিকর্ষণ অণুর আকৃতি ও bond angle নির্ধারণ করে।','H₂O-তে দুই lone pair এবং দুই bond pair; NH₃-তে এক lone pair ও তিন bond pair থাকে। বেশি lone pair বিকর্ষণের ফলে H₂O-তে bond angle প্রায় 104.5°, NH₃-তে প্রায় 107°।','LP–LP > LP–BP > BP–BP (বিকর্ষণের সাধারণ ক্রম)','দুই অণুতেই lone pair আছে বলে তাদের bond angle সমান হবে—এ ধারণা ভুল।','অণুর polarity, আকৃতি এবং intermolecular interaction বোঝার জন্য molecular geometry গুরুত্বপূর্ণ।',['কেন্দ্রীয় পরমাণুর lone pair সংখ্যা গণনা করো।','VSEPR বিকর্ষণের ক্রম প্রয়োগ করো।','দুই অণুর bond angle তুলনা করো।']),
    make('math1-09',9,'assertion',3,'অভিকথন: কোনো ফাংশন x=a বিন্দুতে অন্তরকলনযোগ্য হলে সেখানে অবিচ্ছিন্ন। কারণ: f′(a)-এর সসীম সীমা থাকলে h→0 অবস্থায় [f(a+h)−f(a)]/h-এর লবও শূন্যের দিকে যায়।',['অভিকথন ও কারণ উভয়ই সত্য এবং কারণটি অভিকথনের সঠিক ব্যাখ্যা','অভিকথন ও কারণ উভয়ই সত্য, কিন্তু কারণটি সঠিক ব্যাখ্যা নয়','অভিকথন সত্য, কারণ মিথ্যা','অভিকথন মিথ্যা, কারণ সত্য'],0,'অন্তরকলনযোগ্যতা অবিচ্ছিন্নতার চেয়ে শক্তিশালী শর্ত। কোনো বিন্দুতে সসীম derivative থাকলে ফাংশনটি সেই বিন্দুতে continuous হয়।','f′(a)=lim[h→0] (f(a+h)−f(a))/h সসীম হলে f(a+h)−f(a)=h×quotient; h→0-তে এই পার্থক্য শূন্যে যায়।','lim[x→a] f(x)=f(a)','অবিচ্ছিন্ন হলেই অন্তরকলনযোগ্য—এটি সবসময় সত্য নয়; যেমন f(x)=|x|, x=0-তে continuous কিন্তু differentiable নয়।','স্মুথ গ্রাফ, tangent এবং instantaneous rate of change বিশ্লেষণে continuity ও differentiability আলাদা করে দেখতে হয়।',['Derivative-এর limit definition লেখো।','Difference quotient-এর limit সসীম ব্যবহার করো।','h→0 হলে function value-এর পার্থক্য শূন্য হয়—সিদ্ধান্ত নাও।'])
